// A forwarded message: "[Fwd] <original sender>\n<the message>". Older clients
// just show the tag line; newer ones show a "Forwarded from" label instead.
ChatFwd ParseChatFwd(const std::string& b) {
    ChatFwd f;
    if (b.rfind("[Fwd] ", 0) != 0) return f;
    const std::size_t nl = b.find('\n');
    if (nl == std::string::npos) return f;
    f.ok = true; f.from = b.substr(6, nl - 6); f.body = b.substr(nl + 1);
    return f;
}
static std::string ChatFwdBody(const std::string& from, const std::string& body) {
    const ChatFwd inner = ParseChatFwd(body);   // forwarding a forward keeps the original sender
    return inner.ok ? body : "[Fwd] " + (from.empty() ? std::string("someone") : from) + "\n" + body;
}
// Conversation-list preview: "Photo" / "File: name" instead of raw URLs.
std::string ChatPreviewSmart(const std::string& body, std::size_t n) {
    if (const ChatFwd fw = ParseChatFwd(body); fw.ok) return "Forwarded: " + ChatPreviewSmart(fw.body, n);
    ChatFileInfo fi;
    if (ParseChatFile(body, fi)) return ChatPreview("File: " + fi.name, n);
    if (body.rfind("[Voice] ", 0) == 0) return "Voice message";
    if (body.rfind("[Sticker] ", 0) == 0) return "Sticker";
    { ChatPollInfo pi; if (ParseChatPoll(body, pi)) return ChatPreview("Poll: " + pi.question, n); }
    { ChatInviteInfo ii; if (ParseChatInvite(body, ii)) return ChatPreview("Game invite: " + ii.title, n); }
    if (body.rfind("[JoinRequest] ", 0) == 0) return ChatPreview("Asked to join: " + body.substr(14), n);
    if (body.rfind("[Party] ", 0) == 0) return "Party invite";
    if (body.rfind("[Call] ", 0) == 0) return "Voice call";
    if (body.rfind("[CallEnd] ", 0) == 0) return "Call ended";
    std::string t = body; while (!t.empty() && (t.back() == ' ' || t.back() == '\n')) t.pop_back();
    if (!t.empty() && FirstImageUrl(t) == t) {
        std::string low = t; for (auto& c : low) c = (char)std::tolower((unsigned char)c);
        return low.find(".gif") != std::string::npos ? "GIF" : "Photo";
    }
    if (t.find("<:") != std::string::npos) {   // custom emoji -> ":name:"
        std::string o; std::size_t i = 0;
        while (i < t.size()) {
            std::size_t a = t.find("<:", i);
            if (a == std::string::npos) { o += t.substr(i); break; }
            std::size_t c2 = t.find(':', a + 2), e = t.find('>', a);
            if (c2 == std::string::npos || e == std::string::npos || c2 > e) { o += t.substr(i); break; }
            o += t.substr(i, a - i) + ":" + t.substr(a + 2, c2 - a - 2) + ":";
            i = e + 1;
        }
        return ChatPreview(o, n);
    }
    return ChatPreview(body, n);
}

// ---- Chat attachment upload (background) ---------------------------------------
// Uploading can take seconds, so it runs on a worker (own account service) that
// uploads to Storage and then sends the message; the composer shows progress.
volatile bool g_attBusy = false;   // an upload is in flight
std::string   g_attName;           // file being uploaded (composer status)
static okay::thr::Mutex*    g_attMutex = nullptr;
static bool          g_attDone = false;   // (guarded) finished -> toast result
static std::string   g_attError;          // (guarded) "" on success
static void StartChatUpload(const std::string& path, const std::string& toUid, long toGroup,
                            int voiceSecs = -1, long toChannel = 0);                        // defined below
static void PickAndSendAttachment(const std::string& toUid, long toGroup, long toChannel = 0); // defined below
static constexpr unsigned long long kMaxChatUpload = 25ULL * 1024ULL * 1024ULL;  // matches the bucket limit

// ---- Voice messages ------------------------------------------------------------
// A voice message body is "[Voice] m:ss <url>" — a 16 kHz mono WAV in the "chat"
// bucket (older clients show it as text + a link). Recording drains SDL's
// capture device each frame (queue mode, no callback thread); playback fetches
// the clip once in the background (same worker as avatars) and queues it on an
// output device.
bool ParseChatVoice(const std::string& body, ChatVoiceInfo& out) {
    if (body.rfind("[Voice] ", 0) != 0) return false;
    std::size_t sp = body.find(' ', 8);
    int m = 0, s = 0;
    if (sp == std::string::npos || std::sscanf(body.c_str() + 8, "%d:%d", &m, &s) != 2) return false;
    out.secs = m * 60 + s;
    out.url = body.substr(sp + 1);
    return out.url.rfind("http", 0) == 0;
}
static std::string VoiceClock(int secs) {
    char b[16]; std::snprintf(b, sizeof(b), "%d:%02d", secs / 60, secs % 60); return b;
}
static std::string VoiceMessageBody(int secs, const std::string& url) { return "[Voice] " + VoiceClock(secs) + " " + url; }

static bool EnsureAudio() {
    static int state = 0;   // 0 untried, 1 ok, -1 unavailable
    if (state == 0) {
        okay::platform::InitFlags af; af.video = false; af.audio = true; af.gamepad = false;
        okay::platform::Backend* ab = okay::platform::Default();
        state = (ab && ab->Init(af)) ? 1 : -1;   // starts the audio subsystem on top of what main() already started (shut down with it)
    }
    return state == 1;
}

// Microphone (Messenger-style: tap the mic, talk, then send or bin it).
static constexpr int kVoiceRate = 16000, kVoiceMaxSecs = 120, kVoiceLevelHop = kVoiceRate / 20;
static std::unique_ptr<okay::platform::AudioDevice> g_recDev;
static bool                g_recFake = false;     // dev demo: a recording without a device
static std::vector<Sint16> g_recPcm;
static std::vector<float>  g_recLevels;           // loudness per 50 ms (live meter)
static Uint32              g_recStart = 0;
static std::string         g_recToUid;            // which chat the recording is for
static long                g_recToGroup = 0;
static long                g_recToChannel = 0;    // a server channel (0 = a DM / group)

bool VoiceRecording() { return g_recDev != nullptr || g_recFake; }
bool VoiceRecordingFor(const std::string& uid, long gid, long channel) {
    return VoiceRecording() && g_recToUid == uid && g_recToGroup == gid && g_recToChannel == channel;
}
static float VoiceRecSeconds() { return VoiceRecording() ? (okay::platform::TicksMs32() - g_recStart) / 1000.0f : 0.0f; }
static bool StartVoiceRecord(const std::string& toUid, long toGroup, long toChannel = 0) {
    if (VoiceRecording()) return false;
    if (g_attBusy) { Toast("An upload is already in progress", 2); return false; }
    if (!EnsureAudio()) { Toast("Audio isn't available on this system", 2); return false; }
    okay::platform::AudioSpec want;
    want.freq = kVoiceRate; want.format = okay::platform::SampleFormat::S16; want.channels = 1; want.frames = 1024;
    okay::platform::Backend* pb = okay::platform::Default();
    g_recDev = pb ? pb->OpenAudio(want, true, nullptr, nullptr) : nullptr;   // converted to our format
    if (!g_recDev) { Toast("No microphone found", 2); return false; }
    g_recPcm.clear(); g_recLevels.clear();
    g_recToUid = toUid; g_recToGroup = toGroup; g_recToChannel = toChannel; g_recStart = okay::platform::TicksMs32();
    g_recDev->Pause(false);
    return true;
}
static void PumpVoiceRecord() {   // once per frame: move captured audio into g_recPcm
    if (!g_recDev) return;
    Sint16 buf[2048];
    while (Uint32 got = g_recDev->Dequeue(buf, sizeof(buf)))
        g_recPcm.insert(g_recPcm.end(), buf, buf + got / sizeof(Sint16));
    while ((g_recLevels.size() + 1) * kVoiceLevelHop <= g_recPcm.size()) {
        const Sint16* w = g_recPcm.data() + g_recLevels.size() * kVoiceLevelHop;
        int peak = 0;
        for (int i = 0; i < kVoiceLevelHop; ++i) peak = std::max(peak, std::abs((int)w[i]));
        g_recLevels.push_back(std::min(1.0f, std::sqrt(peak / 32768.0f) * 1.3f));
    }
}
static bool WriteWav16(const std::string& path, const std::vector<Sint16>& pcm, int rate) {
    std::ofstream f(path, std::ios::binary);
    if (!f) return false;
    auto u32 = [&](Uint32 v) { char b[4] = {(char)v, (char)(v >> 8), (char)(v >> 16), (char)(v >> 24)}; f.write(b, 4); };
    auto u16 = [&](Uint16 v) { char b[2] = {(char)v, (char)(v >> 8)}; f.write(b, 2); };
    Uint32 data = (Uint32)pcm.size() * 2;
    f.write("RIFF", 4); u32(36 + data); f.write("WAVE", 4);
    f.write("fmt ", 4); u32(16); u16(1); u16(1); u32(rate); u32(rate * 2); u16(2); u16(16);
    f.write("data", 4); u32(data);
    for (Sint16 s : pcm) u16((Uint16)s);
    return (bool)f;
}
// Stop recording; send=true writes the WAV and hands it to the upload worker.
void FinishVoiceRecord(bool send) {
    if (g_recDev) { PumpVoiceRecord(); g_recDev.reset(); }
    const bool fake = g_recFake; g_recFake = false;
    std::vector<Sint16> pcm; pcm.swap(g_recPcm); g_recLevels.clear();
    if (!send || fake) return;
    if (pcm.size() < (std::size_t)kVoiceRate / 2) { Toast("Too short to send — hold on a little longer", 2); return; }
    std::error_code ec;
    fs::path dir = fs::temp_directory_path(ec) / "okayspace_voice";
    fs::create_directories(dir, ec);
    fs::path file = dir / ("voice-" + std::to_string(okay::platform::TicksMs32()) + ".wav");
    if (!WriteWav16(file.string(), pcm, kVoiceRate)) { Toast("Couldn't save the recording", 2); return; }
    int secs = (int)((pcm.size() + kVoiceRate / 2) / kVoiceRate);
    StartChatUpload(file.string(), g_recToUid, g_recToGroup, std::max(1, secs), g_recToChannel);
}

// Playback: decoded clips by URL + one output device for the clip playing now.
static constexpr int kVoiceBars = 30;
struct VoiceClip {
    bool ok = false;                 // decoded (false = unplayable; don't retry)
    Uint8* pcm = nullptr; Uint32 len = 0;   // points into `owned` (never into an SDL buffer)
    SDL_AudioSpec spec{};
    float secs = 0, bytesPerSec = 1;
    float bars[kVoiceBars] = {};
    std::vector<Uint8> owned;        // the clip's samples (converted to 16-bit when the file was not native 16-bit / float)
    std::map<int, std::vector<Uint8>> fast;   // time-stretched copies by speed index (built on first use)
    VoiceClip() = default;
    // `owned` holds the samples our own decoder gave (okay::wav::LoadWavForSdl); there is
    // no SDL buffer for this destructor to free (#718).
    ~VoiceClip() = default;
    VoiceClip(const VoiceClip&) = delete;             // pcm ownership is exclusive: no shallow copies
    VoiceClip& operator=(const VoiceClip&) = delete;
    VoiceClip(VoiceClip&& o) noexcept { *this = std::move(o); }
    VoiceClip& operator=(VoiceClip&& o) noexcept {
        if (this != &o) {
            ok = o.ok; pcm = o.pcm; len = o.len; spec = o.spec;
            secs = o.secs; bytesPerSec = o.bytesPerSec;
            for (int i = 0; i < kVoiceBars; ++i) bars[i] = o.bars[i];
            owned = std::move(o.owned); fast = std::move(o.fast);
            // pcm pointed into o.owned; vector move transfers that buffer, so the pointer stays valid.
            o.pcm = nullptr; o.len = 0; o.ok = false;
        }
        return *this;
    }
};
static std::map<std::string, VoiceClip> g_voiceClips;
// The platform audio layer plays native-endian 16-bit or float samples. A clip in any other
// PCM layout (8-bit, 32-bit integer, big-endian) is converted to 16-bit once, at load.
static void VoiceClipToPlayable(VoiceClip& c) {
    const SDL_AudioFormat f = c.spec.format;
    if (f == AUDIO_S16SYS || f == AUDIO_F32SYS || !c.pcm || !c.len) return;
    const int width = SDL_AUDIO_BITSIZE(f) / 8;
    if (width < 1 || width > 4) { c.len = 0; return; }
    // Samples already live in c.owned (our own decoder's output), so the bytes are
    // read from `owned` and the old vector storage is released when it is replaced.
    // Nothing here may free them a second time (#718).
    const std::size_t n = c.len / (std::size_t)width;
    std::vector<Uint8> out(n * 2);
    for (std::size_t i = 0; i < n; ++i) {
        const Uint8* p = c.pcm + i * (std::size_t)width;
        float v = 0.0f;   // -1..1
        if (SDL_AUDIO_ISFLOAT(f)) {
            Uint32 u = 0;
            for (int b = 0; b < 4; ++b) u |= (Uint32)p[SDL_AUDIO_ISBIGENDIAN(f) ? 3 - b : b] << (8 * b);
            std::memcpy(&v, &u, 4);
        } else if (width == 1) {
            v = SDL_AUDIO_ISSIGNED(f) ? (float)(Sint8)p[0] / 128.0f : ((float)p[0] - 128.0f) / 128.0f;
        } else {
            Uint32 u = 0;
            for (int b = 0; b < width; ++b) u |= (Uint32)p[SDL_AUDIO_ISBIGENDIAN(f) ? width - 1 - b : b] << (8 * b);
            const long long top = 1ll << (8 * width - 1);
            long long sv = SDL_AUDIO_ISSIGNED(f) ? (long long)(Sint32)(u << (32 - 8 * width)) >> (32 - 8 * width) : (long long)u - top;
            v = (float)sv / (float)top;
        }
        const Sint16 s16 = (Sint16)std::clamp(v * 32767.0f, -32768.0f, 32767.0f);
        std::memcpy(out.data() + i * 2, &s16, 2);
    }
    c.owned = std::move(out);
    c.pcm = c.owned.data(); c.len = (Uint32)c.owned.size();
    c.spec.format = AUDIO_S16SYS;
}
static std::unique_ptr<okay::platform::AudioDevice> g_playDev;
static std::string       g_playUrl;          // clip loaded on g_playDev
static bool              g_playPaused = false;
static Uint32            g_playFrom = 0;     // byte offset the current queue started at
static Uint32            g_playLen = 0;      // length of the buffer playing (the clip, or a sped-up copy)
static const float kVoiceSpeeds[3] = {1.0f, 1.5f, 2.0f};
static const char* const kVoiceSpeedLabels[3] = {"1x", "1.5x", "2x"};

// Speed a voice note up without the chipmunk effect: WSOLA time-stretch
// (overlap-add of 30 ms Hann windows; each window is nudged within +-10 ms to
// the spot that best continues the previous one, so pitch is unchanged).
static std::vector<Sint16> VoiceTimeStretch(const Sint16* in, std::size_t n, int rate, float speed) {
    const int N = std::max(64, rate * 30 / 1000), hopS = N / 2, tol = rate / 100;
    const float hopA = hopS * speed;
    std::vector<float> win((std::size_t)N);
    for (int i = 0; i < N; ++i) win[(std::size_t)i] = 0.5f - 0.5f * std::cos(6.2831853f * i / N);
    const std::size_t outN = (std::size_t)(n / speed) + (std::size_t)N;
    std::vector<float> acc(outN, 0.0f), norm(outN, 0.0f);
    long prev = 0;
    for (long k = 0;; ++k) {
        const long nominal = (long)(k * hopA);
        if (nominal + N + tol >= (long)n) break;
        long pos = nominal;
        if (k > 0) {   // best match for the natural continuation of the previous window
            const long ref = prev + hopS;
            float best = -1e30f;
            for (long dlt = -tol; dlt <= tol; dlt += 2) {
                const long c = nominal + dlt;
                if (c < 0) continue;
                float sum = 0.0f;
                for (int i = 0; i < hopS; i += 4) sum += (float)in[c + i] * (float)in[ref + i];
                if (sum > best) { best = sum; pos = c; }
            }
        }
        const std::size_t o = (std::size_t)k * hopS;
        if (o + (std::size_t)N > outN) break;
        for (int i = 0; i < N; ++i) { acc[o + i] += in[pos + i] * win[(std::size_t)i]; norm[o + i] += win[(std::size_t)i]; }
        prev = pos;
    }
    std::size_t used = outN;
    while (used > 0 && norm[used - 1] < 1e-3f) --used;
    std::vector<Sint16> out(used);
    for (std::size_t i = 0; i < used; ++i)
        out[i] = (Sint16)std::clamp(norm[i] > 1e-3f ? acc[i] / norm[i] : 0.0f, -32768.0f, 32767.0f);
    return out;
}
static std::string       g_voiceWant;        // tapped play before the clip arrived

// Waveform placeholder until the real clip is decoded (stable per URL).
static float VoiceBarStub(const std::string& url, int i) {
    std::size_t h = std::hash<std::string>{}(url) ^ (std::size_t)(i * 2654435761u);
    h ^= h >> 13; h *= 0x5bd1e995; h ^= h >> 15;
    return 0.25f + 0.6f * (float)(h % 1000) / 1000.0f;
}
static fs::path VoiceCachePath(const std::string& url) {
    std::error_code ec;
    fs::path dir = fs::temp_directory_path(ec) / "okayspace_voice";
    fs::create_directories(dir, ec);
    return dir / (std::to_string(std::hash<std::string>{}(url)) + ".wav");
}
// The decoded clip, or nullptr while it downloads (kicked off once, in the background).
static VoiceClip* VoiceClipFor(const std::string& url) {
    auto it = g_voiceClips.find(url);
    if (it != g_voiceClips.end()) return &it->second;
    if (!g_avatarMutex) g_avatarMutex = okay::thr::CreateMutex();
    okay::thr::LockMutex(g_avatarMutex);
    const bool pending = g_avatarPending.count(url) != 0, failed = g_avatarFailed.count(url) != 0;
    okay::thr::UnlockMutex(g_avatarMutex);
    if (pending) return nullptr;
    fs::path cache = VoiceCachePath(url);
    std::error_code ec;
    if (failed || fs::exists(cache, ec)) {
        VoiceClip& c = g_voiceClips[url];
        // Our own decoder (okay::wav::PlaybackClip through LoadWavForSdl) writes the samples
        // straight into the clip's own storage, so no path (a converted clip, an unsupported
        // width, a replaced entry) has a foreign buffer to leave behind (#718).
        SDL_AudioSpec wavSpec{};
        if (!failed && okay::wav::LoadWavForSdl(cache.string(), wavSpec, c.owned)) {
            c.spec = wavSpec;
            c.pcm = c.owned.empty() ? nullptr : c.owned.data();
            c.len = (Uint32)c.owned.size();
            VoiceClipToPlayable(c);
            const int bps = SDL_AUDIO_BITSIZE(c.spec.format) / 8 * std::max<int>(1, c.spec.channels);
            c.bytesPerSec = (float)c.spec.freq * bps;
            c.secs = c.len / c.bytesPerSec;
            c.ok = c.len > 0;
            // Real waveform: peak per slice (16-bit clips; anything else keeps the stub).
            const Uint32 frames = bps ? c.len / bps : 0;
            const bool s16 = c.spec.format == AUDIO_S16LSB || c.spec.format == AUDIO_S16MSB;
            float top = 0.0001f;
            for (int b = 0; b < kVoiceBars; ++b) {
                float peak = 0;
                if (s16 && frames) {
                    Uint32 a = frames * b / kVoiceBars, e = frames * (b + 1) / kVoiceBars;
                    for (Uint32 f = a; f < e; ++f) {
                        Sint16 v; std::memcpy(&v, c.pcm + (std::size_t)f * bps, 2);
                        if (c.spec.format == AUDIO_S16MSB) v = (Sint16)SDL_Swap16((Uint16)v);
                        peak = std::max(peak, std::abs((float)v) / 32768.0f);
                    }
                } else peak = VoiceBarStub(url, b);
                c.bars[b] = peak; top = std::max(top, peak);
            }
            for (float& v : c.bars) v = 0.12f + 0.88f * std::sqrt(v / top);
        }
        return &c;
    }
    okay::thr::LockMutex(g_avatarMutex); g_avatarPending.insert(url); okay::thr::UnlockMutex(g_avatarMutex);
    AvatarDl* d = new AvatarDl{url, cache.string()};
    if (okay::thr::Thread* t = okay::thr::CreateThread(AvatarDlWorker, "okay-voicedl", d)) okay::thr::DetachThread(t);
    else { okay::thr::LockMutex(g_avatarMutex); g_avatarPending.erase(url); okay::thr::UnlockMutex(g_avatarMutex); delete d; }
    return nullptr;
}
static void StopVoice() {
    g_playDev.reset();
    g_playUrl.clear(); g_playPaused = false; g_playFrom = 0; g_playLen = 0;
}
// The samples to play at the chosen speed: the clip itself at 1x, otherwise a
// time-stretched copy (16-bit mono clips, i.e. our own recordings).
static const Uint8* VoiceBuffer(VoiceClip& c, Uint32& len) {
    const int si = std::clamp(g_voiceSpeed, 0, 2);
    const bool s16mono = c.spec.format == AUDIO_S16SYS && c.spec.channels == 1;
    if (si == 0 || !s16mono || c.len < 4) { len = c.len; return c.pcm; }
    auto it = c.fast.find(si);
    if (it == c.fast.end()) {
        auto st = VoiceTimeStretch(reinterpret_cast<const Sint16*>(c.pcm), c.len / 2, c.spec.freq, kVoiceSpeeds[si]);
        std::vector<Uint8> bytes(st.size() * 2);
        if (!st.empty()) std::memcpy(bytes.data(), st.data(), bytes.size());
        it = c.fast.emplace(si, std::move(bytes)).first;
    }
    if (it->second.empty()) { len = c.len; return c.pcm; }
    len = (Uint32)it->second.size();
    return it->second.data();
}
// Start (or restart) a clip at a fraction 0..1 of its length.
static void PlayVoiceAt(const std::string& url, VoiceClip& c, float frac) {
    if (!c.ok) { Toast("Couldn't play this voice message", 2); return; }
    if (!EnsureAudio()) { Toast("Audio isn't available on this system", 2); return; }
    if (g_playUrl != url || !g_playDev) {
        StopVoice();
        okay::platform::AudioSpec want;
        want.freq = c.spec.freq; want.channels = std::max<int>(1, c.spec.channels); want.frames = std::max<int>(256, c.spec.samples);
        want.format = c.spec.format == AUDIO_F32SYS ? okay::platform::SampleFormat::F32 : okay::platform::SampleFormat::S16;   // other formats were converted to s16 at load
        okay::platform::Backend* pb = okay::platform::Default();
        g_playDev = pb ? pb->OpenAudio(want, false, nullptr, nullptr) : nullptr;
        if (!g_playDev) { Toast("No audio output device", 2); return; }
        g_playUrl = url;
    }
    g_playDev->ClearQueued();
    Uint32 len = 0;
    const Uint8* buf = VoiceBuffer(c, len);
    const Uint32 frame = SDL_AUDIO_BITSIZE(c.spec.format) / 8 * std::max<int>(1, c.spec.channels);
    Uint32 off = (Uint32)(std::clamp(frac, 0.0f, 1.0f) * len);
    off -= off % std::max<Uint32>(1, frame);
    if (off >= len) off = 0;
    g_playFrom = off; g_playLen = len;
    g_playDev->Queue(buf + off, len - off);
    g_playDev->Pause(false);
    g_playPaused = false;
}
static float VoicePlayFrac(const std::string& url, const VoiceClip& c) {   // -1 = not this clip
    if (!g_playDev || g_playUrl != url || !c.len) return -1.0f;
    const Uint32 len = g_playLen ? g_playLen : c.len;
    Uint32 left = g_playDev->QueuedBytes();
    return std::min(1.0f, (float)(len - std::min(left, len)) / len);
}
static void PumpVoicePlayback() {   // once per frame: finish clips, start "wanted" ones
    if (g_playDev && !g_playPaused && g_playDev->QueuedBytes() == 0) StopVoice();
    if (!g_voiceWant.empty()) {
        if (VoiceClip* c = VoiceClipFor(g_voiceWant)) { std::string u = g_voiceWant; g_voiceWant.clear(); PlayVoiceAt(u, *c, 0.0f); }
    }
}

static void DrawMicIcon(ImDrawList* d, ImVec2 c, float s, ImU32 col) {
    float w = s * 0.30f, top = c.y - s * 0.44f, h = s * 0.48f;
    d->AddRectFilled(ImVec2(c.x - w * 0.5f, top), ImVec2(c.x + w * 0.5f, top + h), col, w * 0.5f);
    d->PathArcTo(ImVec2(c.x, c.y - s * 0.10f), s * 0.27f, 0.0f, 3.14159265f, 16);
    d->PathStroke(col, 0, 1.7f);
    d->AddLine(ImVec2(c.x, c.y + s * 0.17f), ImVec2(c.x, c.y + s * 0.34f), col, 1.7f);
    d->AddLine(ImVec2(c.x - s * 0.15f, c.y + s * 0.34f), ImVec2(c.x + s * 0.15f, c.y + s * 0.34f), col, 1.7f);
}
static void DrawBinIcon(ImDrawList* d, ImVec2 c, float s, ImU32 col) {
    float w = s * 0.42f, top = c.y - s * 0.22f;
    d->AddLine(ImVec2(c.x - w * 0.62f, top), ImVec2(c.x + w * 0.62f, top), col, 1.7f);
    d->AddLine(ImVec2(c.x - w * 0.18f, top - s * 0.09f), ImVec2(c.x + w * 0.18f, top - s * 0.09f), col, 1.7f);
    d->AddQuad(ImVec2(c.x - w * 0.5f, top + 2), ImVec2(c.x + w * 0.5f, top + 2),
               ImVec2(c.x + w * 0.38f, c.y + s * 0.30f), ImVec2(c.x - w * 0.38f, c.y + s * 0.30f), col, 1.6f);
}

// The voice bubble body: play/pause, waveform (tap to seek), time.
float ChatVoiceWidth(float maxW) { return std::min(maxW, 250.0f); }
void RenderChatVoice(const ChatVoiceInfo& v, float width, bool mine, ImVec4 accent) {
    const float h = 38.0f, r = 16.0f;
    ImVec2 p = ImGui::GetCursorScreenPos();
    ImDrawList* d = ImGui::GetWindowDrawList();
    VoiceClip* clip = VoiceClipFor(v.url);
    const float frac = clip ? VoicePlayFrac(v.url, *clip) : -1.0f;
    const bool playing = frac >= 0.0f && !g_playPaused;
    const bool loading = !clip || g_voiceWant == v.url;

    ImGui::PushID(v.url.c_str());
    // Play / pause disc.
    ImVec2 cc(p.x + r + 1, p.y + h * 0.5f);
    bool tap = ImGui::InvisibleButton("##vplay", ImVec2(r * 2 + 2, h));
    bool hov = ImGui::IsItemHovered();
    const float k = hov ? 1.7f : 1.5f;   // received: a brighter take on the chat colour so it pops off the grey bubble
    ImU32 discC = mine ? okaytheme::Ink(hov ? 255 : 235)
                       : ImGui::GetColorU32(ImVec4(std::min(1.0f, accent.x * k), std::min(1.0f, accent.y * k), std::min(1.0f, accent.z * k), 1.0f));
    ImU32 glyphC = mine ? ImGui::GetColorU32(accent) : okaytheme::OnColorU32();
    d->AddCircleFilled(cc, r, discC, 28);
    if (loading && g_voiceWant == v.url) {   // spinner while the clip downloads
        float t = (float)ImGui::GetTime() * 6.0f;
        d->PathArcTo(cc, r * 0.5f, t, t + 3.14159265f * 1.3f, 16);
        d->PathStroke(glyphC, 0, 2.0f);
    } else if (playing) {
        d->AddRectFilled(ImVec2(cc.x - 5, cc.y - 6), ImVec2(cc.x - 1.5f, cc.y + 6), glyphC, 1.0f);
        d->AddRectFilled(ImVec2(cc.x + 1.5f, cc.y - 6), ImVec2(cc.x + 5, cc.y + 6), glyphC, 1.0f);
    } else {
        d->AddTriangleFilled(ImVec2(cc.x - 4, cc.y - 7), ImVec2(cc.x - 4, cc.y + 7), ImVec2(cc.x + 7, cc.y), glyphC);
    }
    if (hov) ImGui::SetMouseCursor(ImGuiMouseCursor_Hand);
    if (tap) {
        if (!clip) g_voiceWant = (g_voiceWant == v.url) ? std::string() : v.url;
        else if (frac >= 0.0f) { g_playPaused = !g_playPaused; g_playDev->Pause(g_playPaused); }
        else PlayVoiceAt(v.url, *clip, 0.0f);
    }

    // Waveform (tap/drag to seek) + time on the right.
    const int total = clip && clip->ok ? (int)(clip->secs + 0.5f) : v.secs;
    std::string tm = VoiceClock(frac >= 0.0f && clip ? (int)(frac * clip->secs) : total);
    float tw = ImGui::CalcTextSize("0:00").x + 6;
    const float pillW = 34.0f;   // playback-speed pill (1x / 1.5x / 2x), WhatsApp-style
    float wx = p.x + r * 2 + 12, ww = width - (r * 2 + 12) - tw - 6 - pillW - 6;
    ImGui::SameLine(0, 0);
    ImGui::SetCursorScreenPos(ImVec2(wx, p.y));
    if (ImGui::InvisibleButton("##vwave", ImVec2(std::max(10.0f, ww), h)) && clip && clip->ok) {
        PlayVoiceAt(v.url, *clip, (ImGui::GetIO().MousePos.x - wx) / ww);
    }
    if (ImGui::IsItemHovered() && clip && clip->ok) ImGui::SetMouseCursor(ImGuiMouseCursor_Hand);
    const float step = ww / kVoiceBars, bw = std::max(2.0f, step * 0.55f);
    ImU32 onC  = mine ? okaytheme::OnColorU32() : ImGui::GetColorU32(okaytheme::Current().info);
    ImU32 offC = mine ? okaytheme::Ink(105) : okaytheme::TextU32(0.373f);
    for (int b = 0; b < kVoiceBars; ++b) {
        float a = clip && clip->ok ? clip->bars[b] : VoiceBarStub(v.url, b);
        float bh = std::max(3.0f, a * (h - 14));
        float x = wx + b * step;
        bool on = frac >= 0.0f && (b + 0.5f) / kVoiceBars <= frac;
        d->AddRectFilled(ImVec2(x, cc.y - bh * 0.5f), ImVec2(x + bw, cc.y + bh * 0.5f), on ? onC : offC, bw * 0.5f);
    }
    if (frac >= 0.0f) {   // playhead dot
        float hx = wx + frac * (ww - bw) + bw * 0.5f;
        d->AddCircleFilled(ImVec2(hx, cc.y), 5.0f, onC, 14);
    }
    ImVec2 ts = ImGui::CalcTextSize(tm.c_str());
    d->AddText(ImVec2(p.x + width - ts.x, cc.y - ts.y * 0.5f),
               mine ? okaytheme::TextU32(0.902f) : okaytheme::TextU32(0.863f), tm.c_str());
    {   // speed pill: tap to cycle; a clip that's playing continues from the same spot
        const char* sl = kVoiceSpeedLabels[std::clamp(g_voiceSpeed, 0, 2)];
        ImVec2 pp(wx + ww + 6, cc.y - 10);
        ImGui::SetCursorScreenPos(pp);
        const bool ptap = ImGui::InvisibleButton("##vspeed", ImVec2(pillW, 20));
        const bool phov = ImGui::IsItemHovered();
        const bool fast = g_voiceSpeed != 0;
        ImU32 pbg = mine ? okaytheme::Ink(fast ? 70 : (phov ? 45 : 28))
                         : (fast ? ImGui::GetColorU32(ImVec4(accent.x, accent.y, accent.z, 0.85f)) : okaytheme::Ink(phov ? 34 : 20));
        d->AddRectFilled(pp, ImVec2(pp.x + pillW, pp.y + 20), pbg, 10.0f);
        ImVec2 ss = ImGui::CalcTextSize(sl);
        d->AddText(ImVec2(pp.x + (pillW - ss.x) * 0.5f, pp.y + (20 - ss.y) * 0.5f), okaytheme::TextU32(((fast ? 255 : 200) / 255.0f)), sl);
        if (phov) { ImGui::SetMouseCursor(ImGuiMouseCursor_Hand); ImGui::SetTooltip("Playback speed"); }
        if (ptap) {
            g_voiceSpeed = (g_voiceSpeed + 1) % 3;
            SavePrefs();
            if (clip && frac >= 0.0f) {
                const bool wasPaused = g_playPaused;
                PlayVoiceAt(v.url, *clip, frac);
                if (wasPaused) { g_playDev->Pause(true); g_playPaused = true; }
            }
        }
    }
    ImGui::PopID();
    ImGui::SetCursorScreenPos(ImVec2(p.x, p.y + h));
    ImGui::Dummy(ImVec2(width, 0));
}

// Composer while recording: [bin] ● 0:04 ▮▮▮▮ live level  [Send]
void DrawVoiceRecorderBar(float h, ImVec4 sendCol) {
    if (VoiceRecSeconds() >= kVoiceMaxSecs) { FinishVoiceRecord(true); return; }
    const float sendW = 58.0f;
    float w = ImGui::GetContentRegionAvail().x - sendW - 8;
    ImVec2 p = ImGui::GetCursorScreenPos();
    ImDrawList* d = ImGui::GetWindowDrawList();
    d->AddRectFilled(p, ImVec2(p.x + w, p.y + h), okaytheme::U32(okaytheme::kField), 12.0f);
    // Discard.
    ImGui::SetCursorScreenPos(p);
    bool bin = ImGui::InvisibleButton("##vbin", ImVec2(h, h));
    bool bhov = ImGui::IsItemHovered();
    if (bhov) ImGui::SetTooltip("Discard recording");
    DrawBinIcon(d, ImVec2(p.x + h * 0.5f, p.y + h * 0.5f), h * 0.9f, bhov ? okaytheme::DangerFillU32() : okaytheme::TextU32(0.902f));
    // Pulsing red dot + clock.
    float pulse = 0.55f + 0.45f * std::sin((float)ImGui::GetTime() * 5.0f);
    float cy = p.y + h * 0.5f, x = p.x + h + 6;
    d->AddCircleFilled(ImVec2(x + 5, cy), 5.0f, okaytheme::DangerFillU32((((int)(255 * pulse)) / 255.0f)), 16);
    std::string clk = VoiceClock((int)VoiceRecSeconds());
    ImVec2 cs = ImGui::CalcTextSize(clk.c_str());
    d->AddText(ImVec2(x + 16, cy - cs.y * 0.5f), okaytheme::TextU32(), clk.c_str());
    // Live level meter: newest on the right, scrolling left.
    float mx0 = x + 16 + ImGui::CalcTextSize("00:00").x + 10, mx1 = p.x + w - 12;
    const float step = 5.0f;
    int n = (int)((mx1 - mx0) / step);
    for (int i = 0; i < n; ++i) {
        int li = (int)g_recLevels.size() - n + i;
        float lv = li >= 0 ? g_recLevels[li] : 0.0f;
        float bh = std::max(2.0f, lv * (h - 12));
        float bx = mx0 + i * step;
        d->AddRectFilled(ImVec2(bx, cy - bh * 0.5f), ImVec2(bx + 3, cy + bh * 0.5f),
                         li >= 0 ? okaytheme::TextU32(0.863f) : okaytheme::TextU32(0.196f), 1.5f);
    }
    ImGui::SetCursorScreenPos(ImVec2(p.x + w + 8, p.y));
    auto brighten = [](ImVec4 c, float k) { return ImVec4(std::min(1.0f, c.x * k), std::min(1.0f, c.y * k), std::min(1.0f, c.z * k), 1.0f); };
    ImGui::PushStyleColor(ImGuiCol_Button, brighten(sendCol, 1.25f));
    ImGui::PushStyleColor(ImGuiCol_ButtonHovered, brighten(sendCol, 1.45f));
    ImGui::PushStyleVar(ImGuiStyleVar_FrameRounding, 12.0f);
    bool send = ImGui::Button("Send##voice", ImVec2(sendW, h));
    ImGui::PopStyleVar();
    ImGui::PopStyleColor(2);
    if (bin) FinishVoiceRecord(false);
    else if (send) FinishVoiceRecord(true);
}
// New-message chime: a soft two-note "ding" synthesized once (no sound files),
// played on its own output device so it never interrupts a voice note.
void PlayChatChime() {
    if (okayfriends::QuietAlerts(g_onlineStatus)) return;   // Do not disturb: no chat sounds
    if (!g_chatSounds || !EnsureAudio()) return;
    static std::unique_ptr<okay::platform::AudioDevice> dev;
    static std::vector<Sint16> pcm;
    static Uint32 lastAt = 0;
    if (okay::platform::TicksMs32() - lastAt < 1200 && lastAt) return;   // a burst of messages = one chime
    lastAt = okay::platform::TicksMs32();
    const int rate = 22050;
    if (pcm.empty()) {
        const float notes[2] = {880.0f, 1318.5f};             // A5 -> E6
        for (int n = 0; n < 2; ++n) {
            const int len = (int)(rate * (n ? 0.22f : 0.09f));
            for (int i = 0; i < len; ++i) {
                float t = (float)i / rate;
                float env = std::min(1.0f, t * 400.0f) * std::exp(-t * (n ? 14.0f : 22.0f));
                float v = std::sin(6.2831853f * notes[n] * t) + 0.25f * std::sin(6.2831853f * notes[n] * 2.0f * t);
                pcm.push_back((Sint16)(v * env * 5200.0f));
            }
        }
    }
    if (!dev) {
        okay::platform::AudioSpec want;
        want.freq = rate; want.format = okay::platform::SampleFormat::S16; want.channels = 1; want.frames = 512;
        okay::platform::Backend* pb = okay::platform::Default();
        dev = pb ? pb->OpenAudio(want, false, nullptr, nullptr) : nullptr;
        if (!dev) return;
        dev->Pause(false);
    }
    dev->ClearQueued();
    dev->Queue(pcm.data(), (uint32_t)(pcm.size() * sizeof(Sint16)));
}

// Drag & drop target: DrawChatWindow publishes its rectangle and the open
// conversation each frame; the main loop's SDL_DROPFILE handler sends a file
// dropped inside it to that chat.
static bool        g_chatDropOk = false;
static ImVec2      g_chatDropMin, g_chatDropMax;
static std::string g_chatDropUid;
static long        g_chatDropGroup = 0;

// Round mic button that stands in for Send while the composer is empty.
void DrawVoiceMicButton(const char* id, ImVec2 size, ImVec4 col, const std::string& toUid, long toGroup, long toChannel) {
    auto brighten = [](ImVec4 c, float k) { return ImVec4(std::min(1.0f, c.x * k), std::min(1.0f, c.y * k), std::min(1.0f, c.z * k), 1.0f); };
    ImGui::PushStyleColor(ImGuiCol_Button, brighten(col, 1.25f));
    ImGui::PushStyleColor(ImGuiCol_ButtonHovered, brighten(col, 1.45f));
    ImGui::PushStyleVar(ImGuiStyleVar_FrameRounding, 12.0f);
    ImVec2 p = ImGui::GetCursorScreenPos();
    if (size.x <= 0) size.x = ImGui::GetContentRegionAvail().x;
    if (size.y <= 0) size.y = ImGui::GetFrameHeight();
    bool click = ImGui::Button(id, size);
    ImGui::PopStyleVar();
    ImGui::PopStyleColor(2);
    if (ImGui::IsItemHovered()) ImGui::SetTooltip("Record a voice message");
    DrawMicIcon(ImGui::GetWindowDrawList(), ImVec2(p.x + size.x * 0.5f, p.y + size.y * 0.5f),
                std::min(size.y, 26.0f), okaytheme::OnColorU32());
    if (click) StartVoiceRecord(toUid, toGroup, toChannel);
}

// ---- Background chat poll state ---------------------------------------------
// The floating Chat window polled messages (every 4s), typing (every 2.5s),
// conversations (every 6s) and the friend list (every 15s) on the UI thread —
// a steady stream of blocking HTTPS calls that made chat feel laggy. A worker
// thread (ChatPollWorker, own account service) now does all of it and publishes
// here under a mutex; the window renders what's cached and never blocks. User
// actions (send/edit/react/typing-out) stay on the main thread.
std::string g_pollCfgDir, g_pollUrl, g_pollKey;   // account config for worker threads (set once at startup)

// ---- Server-side blocks and privacy settings (docs/sql/blocks.sql) ------------
// The local list (g_blockedUsers, launcher.cfg) is a cache. Block / unblock apply
// at once on this PC, are queued in g_blockPending and sent to the blocks table by
// a worker; once the server answers, its list (plus any still-unsent changes) is
// the truth. Signed out, offline, or SQL not run: the change stays on this PC and
// the Blocked card says so. The first time an account signs in, an old PC-only list
// is uploaded once. All of this state is touched on the UI thread only; the worker
// hands its result over under g_blkMutex.
static int  g_blocksSupport = 0;          // 0 unknown, 1 the server has the table, 2 SQL not run
static std::string g_blocksNote;          // last problem, shown under the Blocked list
static volatile bool g_blkWant = false, g_blkBusy = false, g_blkUserAction = false;
static okay::thr::Mutex* g_blkMutex = nullptr;
struct BlkJob { std::string user; std::vector<okay::privacy::PendingOp> ops; bool userAction = false; };
struct BlkResult {
    bool ready = false, fetched = false, userAction = false, offline = false;
    int support = 0;
    std::string user, message;
    std::vector<okay::privacy::PendingOp> done;
    std::set<std::string> server;
    std::map<std::string, std::string> names;
};
static BlkResult g_blkRes;
static int BlocksWorker(void* p) {
    std::unique_ptr<BlkJob> j(static_cast<BlkJob*>(p));
    BlkResult res; res.user = j->user; res.userAction = j->userAction;
    try {
        okay::account::AccountService a(fs::path(g_pollCfgDir), g_pollUrl, g_pollKey);
        okay::BlockList bl(a);
        bool stop = false;
        for (const auto& o : j->ops) {
            if (stop) break;
            const auto r = o.block ? bl.Block(o.uid, o.name) : bl.Unblock(o.uid);
            if (r.ok) { res.done.push_back(o); continue; }
            res.message = r.message;
            if (r.offline) { res.offline = true; stop = true; }
            else if (r.missing) { res.support = 2; stop = true; }
            else res.done.push_back(o);   // refused for good (not a network problem): drop it so it is not retried forever
        }
        if (!stop) {
            const auto r = bl.Fetch(res.server, res.names);
            if (r.ok) { res.fetched = true; res.support = 1; }
            else { res.message = r.message; if (r.missing) res.support = 2; else if (r.offline) res.offline = true; }
        }
    } catch (...) { res.message = "Could not reach the server."; res.offline = true; }
    okay::thr::LockMutex(g_blkMutex); g_blkRes = std::move(res); g_blkRes.ready = true; okay::thr::UnlockMutex(g_blkMutex);
    g_blkBusy = false;
    return 0;
}
// Block or unblock someone: effective on this PC immediately, then synced.
static void SetBlocked(const std::string& uid, const std::string& name, bool block) {
    if (uid.empty()) return;
    if (block) { g_blockedUsers.insert(uid); if (!name.empty()) g_blockedNames[uid] = name; }
    else { g_blockedUsers.erase(uid); g_blockedNames.erase(uid); }
    okay::privacy::QueueOp(g_blockPending, uid, name, block);
    g_blkWant = true; g_blkUserAction = true;
    SavePrefs();
}
// Call every frame. Drains the worker result and starts a sync when one is due:
// at sign-in, after a change, every minute while changes are unsent, else every 10.
static void PumpBlocks(okay::account::AccountService& account) {
    if (!g_blkMutex) g_blkMutex = okay::thr::CreateMutex();
    BlkResult res; bool have = false;
    okay::thr::LockMutex(g_blkMutex);
    if (g_blkRes.ready) { res = std::move(g_blkRes); g_blkRes = BlkResult(); have = true; }
    okay::thr::UnlockMutex(g_blkMutex);
    const std::string user = account.IsLoggedIn() ? account.CurrentSession().username : std::string();
    if (have && res.user == user) {
        for (const auto& d : res.done)
            g_blockPending.erase(std::remove_if(g_blockPending.begin(), g_blockPending.end(),
                [&](const okay::privacy::PendingOp& o) { return o == d; }), g_blockPending.end());
        if (res.support == 2) g_blocksSupport = 2; else if (res.support == 1) g_blocksSupport = 1;
        if (res.fetched) {
            g_blockedUsers = okay::privacy::ApplyPending(res.server, g_blockPending);
            for (const auto& uid : g_blockedUsers) {
                auto it = res.names.find(uid);
                if (it != res.names.end() && !it->second.empty()) g_blockedNames[uid] = it->second;
            }
            for (auto it = g_blockedNames.begin(); it != g_blockedNames.end();)
                it = g_blockedUsers.count(it->first) ? std::next(it) : g_blockedNames.erase(it);
            g_blocksSyncedFor = res.user;
            g_blocksNote.clear();
        } else if (!res.message.empty()) g_blocksNote = res.message;
        if (res.userAction) {
            if (res.fetched && g_blockPending.empty()) Toast("Saved to your account", 1);
            else if (res.support == 2) Toast("Saved on this PC only: the server has no block list yet (docs/sql/blocks.sql).", 2);
            else Toast("Saved on this PC. Will sync to your account when the server is reachable.", 0);
        }
        SavePrefs();
    }
    static std::string lastUser; static Uint32 next = 0;
    if (user.empty() || !account.IsOnline() || g_pollCfgDir.empty()) {
        lastUser.clear();
        return;
    }
    if (user != lastUser) {
        lastUser = user; g_blkWant = true;
        if (okay::privacy::ClassifyLocalList(g_blocksSyncedFor, user) == okay::privacy::LocalListAction::DiscardOtherAccount) {
            g_blockedUsers.clear(); g_blockedNames.clear(); g_blockPending.clear(); g_blocksSyncedFor = user; SavePrefs();   // that list was another account's
        }
    }
    const Uint32 now = okay::platform::TicksMs32();
    if (g_blkBusy || (!g_blkWant && now < next)) return;
    g_blkWant = false;
    next = now + (g_blockPending.empty() ? 600000u : 60000u);
    auto* job = new BlkJob;
    job->user = user; job->userAction = g_blkUserAction; g_blkUserAction = false;
    job->ops = g_blockPending;
    if (g_blocksSyncedFor.empty())   // the old PC-only list: upload it once
        for (const auto& uid : g_blockedUsers) {
            bool queued = false; for (const auto& o : job->ops) if (o.uid == uid) queued = true;
            if (!queued) { auto it = g_blockedNames.find(uid); job->ops.push_back({uid, it != g_blockedNames.end() ? it->second : std::string(), true}); }
        }
    g_blkBusy = true;
    if (okay::thr::Thread* t = okay::thr::CreateThread(BlocksWorker, "okay-blocks", job)) okay::thr::DetachThread(t);
    else { g_blkBusy = false; delete job; }
}

// Privacy settings (who can message / see me): the local values are a cache of the
// privacy_settings row. At sign-in the server's row wins (or, if there is none, the
// local values are saved as the first row); afterwards every change is pushed.
static int  g_privSupport = 0;            // 0 unknown, 1 saved on the server, 2 SQL not run
static std::string g_privNote;            // last problem, shown under the settings
static volatile bool g_privDirty = false, g_privBusy = false;
struct PrivResult { bool ready = false, fetched = false, saved = false, offline = false; int support = 0; std::string user, message; okay::privacy::Settings s; };
static PrivResult g_privRes; static okay::thr::Mutex* g_privMutex = nullptr;
struct PrivJob { std::string user; okay::privacy::Settings local; bool save = false; };
static okay::privacy::Settings CurrentPrivacy() { return {g_dmFrom, g_profileVis, g_onlineVis, g_friendReqs, g_callsFrom}; }
static void MarkPrivacyChanged() { g_privDirty = true; SavePrefs(); }
static int PrivacyWorker(void* p) {
    std::unique_ptr<PrivJob> j(static_cast<PrivJob*>(p));
    PrivResult res; res.user = j->user;
    try {
        okay::account::AccountService a(fs::path(g_pollCfgDir), g_pollUrl, g_pollKey);
        okay::BlockList bl(a);
        okay::BlockList::Outcome r;
        if (!j->save) {
            bool found = false; okay::privacy::Settings s = j->local;
            r = bl.FetchSettings(s, found);
            if (r.ok && found) { res.fetched = true; res.s = s; }
            else if (r.ok) { r = bl.SaveSettings(j->local); res.saved = r.ok; }   // first time: the local values become the row
        } else { r = bl.SaveSettings(j->local); res.saved = r.ok; }
        res.support = r.ok ? 1 : r.missing ? 2 : 0; res.offline = r.offline;
        if (!r.ok) res.message = r.message;
    } catch (...) { res.offline = true; res.message = "Could not reach the server."; }
    okay::thr::LockMutex(g_privMutex); g_privRes = std::move(res); g_privRes.ready = true; okay::thr::UnlockMutex(g_privMutex);
    g_privBusy = false;
    return 0;
}
static void PumpPrivacy(okay::account::AccountService& account) {
    if (!g_privMutex) g_privMutex = okay::thr::CreateMutex();
    PrivResult res; bool have = false;
    okay::thr::LockMutex(g_privMutex);
    if (g_privRes.ready) { res = std::move(g_privRes); g_privRes = PrivResult(); have = true; }
    okay::thr::UnlockMutex(g_privMutex);
    const std::string user = account.IsLoggedIn() ? account.CurrentSession().username : std::string();
    static std::string syncedUser; static Uint32 retryAt = 0;
    if (have && res.user == user) {
        if (res.support) g_privSupport = res.support;
        if (res.fetched && !g_privDirty) {   // (a change made meanwhile is newer than the fetched row)
            g_dmFrom = res.s.dmFrom; g_profileVis = res.s.profileVis; g_onlineVis = res.s.onlineVis;
            g_friendReqs = res.s.friendRequests; g_callsFrom = res.s.callsFrom;
            SavePrefs();
        }
        if (res.fetched || res.saved) { g_privNote.clear(); syncedUser = user; }
        else if (res.support == 2) { g_privNote = okay::privacy::SetupNote(); syncedUser = user; g_privDirty = false; }
        else { g_privNote = res.message; retryAt = okay::platform::TicksMs32() + 30000; if (!res.fetched) g_privDirty = true; }
    }
    if (user.empty() || !account.IsOnline() || g_pollCfgDir.empty()) { syncedUser.clear(); return; }
    if (g_privBusy || okay::platform::TicksMs32() < retryAt) return;
    const bool initial = syncedUser != user;
    if (!initial && !g_privDirty) return;
    auto* job = new PrivJob; job->user = user; job->local = CurrentPrivacy(); job->save = !initial || g_privDirty;   // a change made before the first sync wins over the server row
    g_privDirty = false; retryAt = 0; g_privBusy = true;
    if (okay::thr::Thread* t = okay::thr::CreateThread(PrivacyWorker, "okay-privacy", job)) okay::thr::DetachThread(t);
    else { g_privBusy = false; g_privDirty = true; delete job; }
}
// ---- Sending crash reports (docs/online/crash_reports.md, shared/CrashUpload.hpp) ----
// A new report in okay_crashlog.txt is scrubbed and sent as one row of the Supabase table crash_reports by a worker thread. The rules (the
// Settings switch and OKAY_CRASH_UPLOAD=0, at most 5 a day, never twice, retry after a pause, 64 KB, the notice before the first send, the anon key may only insert) are
// shared/CrashUpload.hpp's and are tested there; this part only runs them. The sent / refused ids are kept in okay_crash_sent.txt next to
// the reports. State is touched on the UI thread only; the worker hands its answer over under g_crashUpMutex.
static std::string g_crashUpNote;                        // the last result, one plain sentence, shown on the Crash reports page
static volatile bool g_crashUpBusy = false;
static okay::thr::Mutex* g_crashUpMutex = nullptr;
struct CrashUpJob { std::vector<okaycrash::Report> reports; std::string ledgerPath; okaycrash::ScrubContext ctx; std::string nowLocal; };
struct CrashUpResult { bool ready = false; std::string note; int sent = 0; };
static CrashUpResult g_crashUpRes;
static bool g_crashUpResetSince = false;                 // the switch was just turned on: only crashes from now on are sent (the pump records the moment)
static std::string LocalNowText() {                      // "2026-11-15 12:00:00", local time: the format the editor writes in a report's When line
    const std::time_t t = std::time(nullptr);
    char b[32] = "";
    if (const std::tm* lt = std::localtime(&t)) std::strftime(b, sizeof(b), "%Y-%m-%d %H:%M:%S", lt);
    return b;
}
static int CrashUploadWorker(void* p) {
    std::unique_ptr<CrashUpJob> j(static_cast<CrashUpJob*>(p));
    CrashUpResult res;
    try {
        okaycrash::upload::Ledger ledger;
        okaycrash::upload::LoadLedger(j->ledgerPath, ledger);
        if (!okaycrash::upload::SaveLedger(j->ledgerPath, ledger)) {   // cannot remember what was sent = would send twice: send nothing
            res.note = "Crash reports were not sent: the launcher cannot write okay_crash_sent.txt next to the editor.";
        } else {
            okay::account::AccountService a(fs::path(g_pollCfgDir), g_pollUrl, g_pollKey);
            auto send = [&](const okaycrash::upload::Request& q) {
                okaycrash::upload::Reply r;
                const auto resp = a.ApiAnon(q.path, q.method, q.body, q.header);   // the public key only: the table accepts inserts from it and nothing else
                r.reached = resp.reached; r.status = resp.status; r.body = resp.body;
                return r;
            };
            okaycrash::upload::Options o;
            o.now = (long)std::time(nullptr);
            o.nowLocal = j->nowLocal;
            const okaycrash::upload::Result out = okaycrash::upload::Run(j->reports, ledger, send, j->ctx, o);
            if (out.changedLedger && !okaycrash::upload::SaveLedger(j->ledgerPath, ledger))
                res.note = "Sent, but could not save okay_crash_sent.txt (the same report may be sent again).";
            else res.note = out.note;
            res.sent = out.sent + out.duplicates;
        }
    } catch (...) { res.note = "Could not send crash reports."; }
    okay::thr::LockMutex(g_crashUpMutex); g_crashUpRes = std::move(res); g_crashUpRes.ready = true; okay::thr::UnlockMutex(g_crashUpMutex);
    g_crashUpBusy = false;
    return 0;
}
static void PumpCrashUpload() {
    if (!g_crashUpMutex) g_crashUpMutex = okay::thr::CreateMutex();
    okay::thr::LockMutex(g_crashUpMutex);
    if (g_crashUpRes.ready) {
        g_crashUpNote = g_crashUpRes.note;
        if (g_crashUpRes.sent > 0) Toast("Crash report sent. Thank you.", 1);
        g_crashUpRes = CrashUpResult();
    }
    okay::thr::UnlockMutex(g_crashUpMutex);
    static Uint32 next = 0;
    const Uint32 now = okay::platform::TicksMs32();
    if (g_crashUpBusy || (now < next && !g_crashUpResetSince)) return;
    next = now + 20000;   // a look every 20 seconds is plenty
    const fs::path dir = CrashDir();
    if (dir.empty()) return;
    std::error_code ec;
    {   // The ledger follows the switch: the first run on this computer (no ledger yet) and the switch just turned on both start "from now"; while sending is off
        // (the Settings switch or OKAY_CRASH_UPLOAD=0) the ledger is marked paused, and the first look after it comes back on moves "since" to now. Reports from
        // before that moment are never sent.
        const std::string ledgerFile = (dir / okaycrash::upload::kLedgerName).string();
        okaycrash::upload::Ledger l;
        okaycrash::upload::LoadLedger(ledgerFile, l);   // (what was already sent is kept)
        const std::string nowText = LocalNowText();
        bool changed = false;
        if (g_crashUpResetSince || !fs::exists(ledgerFile, ec)) { l.SetSince(nowText); l.SetPaused(false); changed = true; }
        if (okaycrash::upload::FollowSwitch(l, CrashUploadOn(), nowText)) changed = true;
        if (changed) okaycrash::upload::SaveLedger(ledgerFile, l);
        g_crashUpResetSince = false;
    }
    if (!CrashUploadOn() || g_pollCfgDir.empty() || g_crashes.empty()) return;
    const fs::path hist = fs::exists(dir / "okay_crashlog.txt", ec) ? dir / "okay_crashlog.txt" : dir / "okay_crash.txt";
    const auto age = fs::file_time_type::clock::now() - fs::last_write_time(hist, ec);
    if (ec || age < std::chrono::seconds(15)) return;   // let the editor finish writing (and, on Windows, naming the frames) first
    okaycrash::upload::Ledger ledger;
    okaycrash::upload::LoadLedger((dir / okaycrash::upload::kLedgerName).string(), ledger);
    okaycrash::upload::Options o;
    o.now = (long)std::time(nullptr);
    if (ledger.Paused() || ledger.RetryAfter() > o.now) return;
    switch (okaycrash::upload::NextStep(CrashUploadOn(), g_crashNoticeSeen, okaycrash::upload::Pending(g_crashes, ledger, o).size())) {
        case okaycrash::upload::Step::Idle: return;
        case okaycrash::upload::Step::ShowNotice: g_crashNoticeReq = true; return;   // the main loop shows the notice; the first report goes after it has been answered
        case okaycrash::upload::Step::Send: break;
    }
    auto* job = new CrashUpJob;
    job->reports = g_crashes;
    job->ledgerPath = (dir / okaycrash::upload::kLedgerName).string();
    job->ctx = okaycrash::LocalContext();
    job->nowLocal = LocalNowText();
    g_crashUpBusy = true;
    if (okay::thr::Thread* t = okay::thr::CreateThread(CrashUploadWorker, "okay-crashup", job)) okay::thr::DetachThread(t);
    else { g_crashUpBusy = false; delete job; }
}
static okay::thr::Mutex*  g_chatMutex = nullptr;
static okay::thr::Thread* g_chatThread = nullptr;
static volatile bool g_chatPollRun = true;
static volatile bool g_chatPeerTyping = false;
volatile bool g_chatForceLog = false;   // a send/edit/react asks for an immediate re-poll

// ---- Outbox: a sent message shows up instantly; the network send runs off-thread ----
// (Sending used to block the UI on the HTTP request, and the message only
// appeared after the next poll.) Each entry renders as a "Sending" bubble until
// the conversation log contains it; a failed send offers Retry / Discard.
struct OutMsg {
    long localId = 0; std::string toUid; long toGroup = 0; long toChannel = 0; std::string body; long replyTo = 0;
    int state = 0;            // 0 queued/sending, 1 sent (waiting for the log), -1 failed
    std::string err;          // why it failed, when the server said (e.g. a privacy rule: "This person does not accept messages from you.")
    long when = 0; Uint32 sentAt = 0;
};
static okay::thr::Mutex* g_outMutex = nullptr;
static std::vector<OutMsg> g_outbox;   // (guarded)
static bool g_outWorkerRunning = false; // (guarded)
static long g_outNextId = 1;
static volatile bool g_srvForce = false; // Servers poller: refresh now (set after a channel post lands)
static void OutboxKick();               // starts the sender thread (defined with the chat workers)
void OutboxSend(const std::string& toUid, long toGroup, const std::string& body, long replyTo, long toChannel) {
    if (body.empty()) return;
    if (!g_outMutex) g_outMutex = okay::thr::CreateMutex();
    OutMsg o; o.localId = g_outNextId++; o.toUid = toUid; o.toGroup = toGroup; o.toChannel = toChannel;
    o.body = body; o.replyTo = replyTo;
    o.when = (long)std::time(nullptr);
    okay::thr::LockMutex(g_outMutex); g_outbox.push_back(o); okay::thr::UnlockMutex(g_outMutex);
    OutboxKick();
}
// Server channel replies and threads ride in the message text (the table has
// no reply column): "[re:ID] text" answers message ID inline, "[th:ID] text" is
// a reply inside ID's thread, kept out of the main channel. Older clients just
// show the tag.
struct SvBody { int kind = 0; long ref = 0; std::string text; };   // 0 plain, 1 reply, 2 thread reply
static SvBody ParseSvBody(const std::string& b) {
    SvBody r; r.text = b;
    if (b.size() > 5 && b[0] == '[' && (b.compare(1, 3, "re:") == 0 || b.compare(1, 3, "th:") == 0)) {
        const std::size_t e = b.find(']');
        const long id = std::atol(b.c_str() + 4);
        if (e != std::string::npos && e < 24 && id > 0) {
            r.kind = b[1] == 'r' ? 1 : 2; r.ref = id; r.text = b.substr(e + 1);
            if (!r.text.empty() && r.text[0] == ' ') r.text.erase(0, 1);
        }
    }
    return r;
}
static std::string SvTag(int kind, long ref) { return kind == 0 || ref <= 0 ? std::string() : std::string(kind == 1 ? "[re:" : "[th:") + std::to_string(ref) + "] "; }

// ============================================================================
// Chat extras: shared pins, edit history, scheduled messages, custom status,
// search across every chat and forwarding. Network calls run on short-lived
// worker threads with their own account service (the same as reactions), so
// the chat never waits on the network.
// ============================================================================
bool ChatDemo() { static const bool d = std::getenv("OKAY_CHAT_DEMO") != nullptr; return d; }

// ---- Pinned messages -----------------------------------------------------------
static Uint32 g_pinsTouchedMs = 0;   // a local pin change: polled pins wait a moment (no flicker)
struct ChatPinJob { bool group = false; long id = 0; bool on = false; };
static int ChatPinWorker(void* p) {
    std::unique_ptr<ChatPinJob> j(static_cast<ChatPinJob*>(p));
    try {
        okay::account::AccountService a(fs::path(g_pollCfgDir), g_pollUrl, g_pollKey);
        okay::Messages(a).Pin(j->group ? "group" : "dm", j->id, j->on);
    } catch (...) {}
    g_chatForceLog = true;
    return 0;
}
static void ChatPinAsync(bool group, long id, bool on) {
    auto* j = new ChatPinJob{group, id, on};
    if (okay::thr::Thread* t = okay::thr::CreateThread(ChatPinWorker, "okay-pin", j)) okay::thr::DetachThread(t);
    else delete j;
}
bool ChatIsPinned(bool group, long id) { return (group ? g_pinsGroup : g_pinsDm).count(id) != 0; }
void ChatPinToggle(bool group, long id) {
    auto& m = group ? g_pinsGroup : g_pinsDm;
    const bool on = m.count(id) == 0;
    if (on) m[id] = (long)std::time(nullptr); else m.erase(id);
    g_pinsTouchedMs = okay::platform::TicksMs32();
    if (g_pinsShared && !ChatDemo()) ChatPinAsync(group, id, on);
    else SavePrefs();
    Toast(on ? "Message pinned" : "Message unpinned", 1);
}
// Pins published by the chat poller: everything the server says I can see.
static bool g_chatPinsReady = false, g_chatPinsSupported = true;   // (guarded by g_chatMutex)
static std::map<long, long> g_chatPinsDmIn, g_chatPinsGroupIn;      // (guarded)
// Apply them on the UI thread. The first time the server confirms it keeps
// pins, any device-only pins are uploaded so nothing is lost.
static void ChatApplyPolledPins(const std::map<long, long>& dmPins, const std::map<long, long>& grPins, bool supported) {
    if (!supported) { if (g_pinsShared) { g_pinsShared = false; SavePrefs(); } return; }
    if (!g_pinsShared) {
        g_pinsShared = true;
        std::map<long, long> d = dmPins, g = grPins;
        for (const auto& kv : g_pinsDm)    if (!d.count(kv.first)) { d[kv.first] = kv.second; ChatPinAsync(false, kv.first, true); }
        for (const auto& kv : g_pinsGroup) if (!g.count(kv.first)) { g[kv.first] = kv.second; ChatPinAsync(true, kv.first, true); }
        g_pinsDm = d; g_pinsGroup = g;
        SavePrefs();   // drops the device-only copies
        return;
    }
    if (okay::platform::TicksMs32() - g_pinsTouchedMs < 3000) return;
    g_pinsDm = dmPins; g_pinsGroup = grPins;
}

// The strip under a conversation's header: the newest pinned message (click to
// jump; clicking again walks back through older pins, Telegram-style), a count,
// and a list button with every pin (jump / unpin).
void DrawPinnedBar(const char* id, std::vector<ChatPinRef> pins, bool group, long& jumpTo) {
    if (pins.empty()) return;
    std::sort(pins.begin(), pins.end(), [](const ChatPinRef& a, const ChatPinRef& b) { return a.when > b.when; });
    static std::map<std::string, int> s_idx;      // which pin each chat's bar shows
    int& idx = s_idx[id];
    if (idx >= (int)pins.size()) idx = 0;
    const ChatPinRef& cur = pins[(std::size_t)idx];
    ImGui::PushID(id);
    ImGui::PushStyleColor(ImGuiCol_ChildBg, okaytheme::kField);
    ImGui::PushStyleVar(ImGuiStyleVar_ChildRounding, 8.0f);
    ImGui::BeginChild("##pinbar", ImVec2(0, 34), false, ImGuiWindowFlags_NoScrollbar | ImGuiWindowFlags_NoScrollWithMouse);
    ImDrawList* d = ImGui::GetWindowDrawList();
    const ImVec2 wp = ImGui::GetWindowPos(), ws = ImGui::GetWindowSize();
    // Segment marks on the left edge: one per pin, the shown one bright.
    const int n = std::min((int)pins.size(), 4);
    const float segH = (ws.y - 10.0f - (n - 1) * 2.0f) / n;
    for (int k = 0; k < n; ++k) {
        const float y0 = wp.y + 5.0f + k * (segH + 2.0f);
        const bool on = std::min(idx, n - 1) == k;
        d->AddRectFilled(ImVec2(wp.x + 8, y0), ImVec2(wp.x + 11, y0 + segH),
                         on ? ImGui::GetColorU32(kAccent) : ImGui::GetColorU32(ImVec4(kAccent.x, kAccent.y, kAccent.z, 0.35f)), 1.5f);
    }
    const float tx = wp.x + 20.0f;
    char head[48];
    if (pins.size() > 1) std::snprintf(head, sizeof(head), "Pinned message %d of %d", idx + 1, (int)pins.size());
    else std::snprintf(head, sizeof(head), "Pinned message");
    const float fs = ImGui::GetFontSize() * 0.86f;
    d->AddText(ImGui::GetFont(), fs, ImVec2(tx, wp.y + 3), ImGui::GetColorU32(kAccent), head);
    DrawRichLine(d, ImVec2(tx, wp.y + 3 + fs + 1), ImGui::GetColorU32(ImGuiCol_Text), cur.preview, ws.x - 20.0f - 46.0f);
    // Click anywhere left of the list button: jump, then advance to the next older pin.
    ImGui::SetCursorScreenPos(wp);
    if (ImGui::InvisibleButton("##pinjump", ImVec2(ws.x - 40.0f, ws.y))) { jumpTo = cur.id; idx = (idx + 1) % (int)pins.size(); }
    if (ImGui::IsItemHovered()) {
        ImGui::SetMouseCursor(ImGuiMouseCursor_Hand);
        ImGui::SetTooltip(pins.size() > 1 ? "Go to this message (click again for the next pin)" : "Go to this message");
    }
    // List button: every pin in this chat.
    ImGui::SetCursorScreenPos(ImVec2(wp.x + ws.x - 36.0f, wp.y + 3.0f));
    const ImVec2 lb = ImGui::GetCursorScreenPos();
    if (ImGui::InvisibleButton("##pinlist", ImVec2(28, 28))) ImGui::OpenPopup("##pinlistpop");
    const bool lh = ImGui::IsItemHovered();
    if (lh) { d->AddRectFilled(lb, ImVec2(lb.x + 28, lb.y + 28), okaytheme::Ink(20), 6.0f); ImGui::SetTooltip("All pinned messages"); }
    {
        const ImU32 ic = ImGui::GetColorU32(lh ? ImGuiCol_Text : ImGuiCol_TextDisabled);
        for (int k = 0; k < 3; ++k) {
            const float y = lb.y + 9.0f + k * 5.0f;
            d->AddCircleFilled(ImVec2(lb.x + 8.5f, y), 1.3f, ic, 6);
            d->AddLine(ImVec2(lb.x + 12, y), ImVec2(lb.x + 21, y), ic, 1.5f);
        }
    }
    ImGui::EndChild();
    ImGui::PopStyleVar();
    ImGui::PopStyleColor();
    ImGui::SetNextWindowSizeConstraints(ImVec2(300, 0), ImVec2(440, 380));
    if (ImGui::BeginPopup("##pinlistpop")) {
        ImGui::TextDisabled("Pinned messages (%d)", (int)pins.size());
        ImGui::Separator();
        long unpin = 0;
        for (std::size_t k = 0; k < pins.size(); ++k) {
            const ChatPinRef& p = pins[k];
            ImGui::PushID((int)k);
            const ImVec2 sp = ImGui::GetCursorScreenPos();
            const float rw = ImGui::GetContentRegionAvail().x - 30.0f, rh = ImGui::GetTextLineHeight() * 2.0f + 6.0f;
            if (ImGui::Selectable("##pinrow", false, 0, ImVec2(rw, rh))) { jumpTo = p.id; idx = (int)k; ImGui::CloseCurrentPopup(); }
            ImDrawList* pd = ImGui::GetWindowDrawList();
            std::string top = p.who.empty() ? std::string() : p.who;
            if (p.when > 0) top += (top.empty() ? "" : "  \xC2\xB7  ") + std::string("pinned ") + RelTime(p.when);
            pd->AddText(ImVec2(sp.x + 2, sp.y + 2), ImGui::GetColorU32(ImGuiCol_TextDisabled), top.c_str());
            DrawRichLine(pd, ImVec2(sp.x + 2, sp.y + 4 + ImGui::GetTextLineHeight()), ImGui::GetColorU32(ImGuiCol_Text), p.preview, rw - 4);
            ImGui::SameLine();
            if (ImGui::SmallButton("x")) unpin = p.id;
            if (ImGui::IsItemHovered()) ImGui::SetTooltip("Unpin");
            ImGui::PopID();
        }
        if (unpin) ChatPinToggle(group, unpin);
        ImGui::EndPopup();
    }
    ImGui::PopID();
    ImGui::Dummy(ImVec2(0, 4));
}

// ---- Edit history ------------------------------------------------------------------
// Save an edit: the old text is recorded first (message_edits), then the new
// text is written. Recording is best-effort: a server without the table still
// saves the edit itself.
bool ChatSaveEdit(okay::Messages& dm, bool group, long id, const std::string& oldBody, const std::string& newBody) {
    if (oldBody == newBody) return true;
    if (!oldBody.empty()) dm.RecordEdit(group ? "group" : "dm", id, oldBody);
    return group ? dm.EditGroup(id, newBody) : dm.Edit(id, newBody);
}
struct EditHistView { bool open = false; std::string scope; long id = 0; std::string current; bool supported = true;
                      std::vector<okay::Messages::EditVersion> versions; };
static EditHistView g_editHist;
void OpenEditHistory(okay::Messages& dm, bool group, long id, const std::string& current) {
    g_editHist = EditHistView{};
    g_editHist.open = true; g_editHist.scope = group ? "group" : "dm"; g_editHist.id = id; g_editHist.current = current;
    if (ChatDemo()) {   // dev screenshot data
        const long t = (long)std::time(nullptr);
        g_editHist.versions = {{"sure, ping me when your free", t - 470}, {"sure, ping me when you're free!", t - 465}};
        return;
    }
    g_editHist.versions = dm.EditHistory(g_editHist.scope, id, &g_editHist.supported);
}
static void DrawEditHistoryPopup() {
    if (g_editHist.open) { ImGui::OpenPopup("Edit history"); g_editHist.open = false; }
    ImGui::SetNextWindowSize(ImVec2(420, 0), ImGuiCond_Appearing);
    ImGui::SetNextWindowSizeConstraints(ImVec2(320, 0), ImVec2(560, 520));
    if (ImGui::BeginPopupModal("Edit history", nullptr, ImGuiWindowFlags_AlwaysAutoResize)) {
        const float w = 400.0f;
        auto version = [&](const char* id, const char* label, const std::string& body, bool now) {
            ImGui::PushStyleColor(ImGuiCol_ChildBg, now ? ImVec4(kAccentDim.x, kAccentDim.y, kAccentDim.z, 0.55f) : okaytheme::kField);
            ImGui::PushStyleVar(ImGuiStyleVar_ChildRounding, 10.0f);
            ImGui::PushStyleVar(ImGuiStyleVar_WindowPadding, ImVec2(12, 8));
            ImGui::BeginChild(id, ImVec2(w, 0), ImGuiChildFlags_AutoResizeY | ImGuiChildFlags_AlwaysUseWindowPadding);
            ImGui::TextDisabled("%s", label);
            RenderChatBody(body, ImGui::GetContentRegionAvail().x);
            ImGui::EndChild();
            ImGui::PopStyleVar(2);
            ImGui::PopStyleColor();
            ImGui::Dummy(ImVec2(0, 2));
        };
        if (!g_editHist.supported)
            ImGui::TextWrapped("Earlier versions aren't kept on this server yet (an admin needs to run docs/sql/chat_extras.sql).");
        else if (g_editHist.versions.empty())
            ImGui::TextDisabled("No earlier versions were saved for this message.");
        for (std::size_t i = 0; i < g_editHist.versions.size(); ++i) {
            const auto& v = g_editHist.versions[i];
            char lbl[96], id[16];
            std::snprintf(lbl, sizeof(lbl), "%s  \xC2\xB7  replaced %s", i == 0 ? "Original" : "Earlier version",
                          v.when > 0 ? RelTime(v.when).c_str() : "");
            std::snprintf(id, sizeof(id), "##v%d", (int)i);
            version(id, lbl, v.body, false);
        }
        version("##cur", "Now", g_editHist.current, true);
        ImGui::Dummy(ImVec2(0, 4));
        if (ImGui::Button("Close", ImVec2(okl::FitButtonW("Close", okl::UiPx(100.0f)), 0)) || ImGui::IsKeyPressed(ImGuiKey_Escape)) ImGui::CloseCurrentPopup();
        ImGui::EndPopup();
    }
}

// ---- Scheduled messages ------------------------------------------------------------
// Kept in scheduled.cfg next to the launcher and sent by this launcher when
// they're due (so it has to be running then; anything overdue goes out the
// next time it starts). One line each: id, time, group, uid, name, body
// (tabs/newlines escaped).
static std::string SchedEsc(const std::string& s) {
    std::string o;
    for (char c : s) { if (c == '\\') o += "\\\\"; else if (c == '\n') o += "\\n"; else if (c == '\t') o += "\\t"; else if (c != '\r') o += c; }
    return o;
}
static std::string SchedUnesc(const std::string& s) {
    std::string o;
    for (std::size_t i = 0; i < s.size(); ++i) {
        if (s[i] == '\\' && i + 1 < s.size()) { char e = s[++i]; o += e == 'n' ? '\n' : e == 't' ? '\t' : e; }
        else o += s[i];
    }
    return o;
}
static void SaveScheduled() {
    std::ofstream f(fs::path(g_exeDir) / "scheduled.cfg", std::ios::trunc);
    for (const auto& m : g_scheduled)
        f << m.id << '\t' << m.at << '\t' << m.toGroup << '\t' << SchedEsc(m.toUid) << '\t' << SchedEsc(m.toName) << '\t' << SchedEsc(m.body) << '\n';
}
static void LoadScheduled() {
    g_scheduled.clear();
    std::ifstream f(fs::path(g_exeDir) / "scheduled.cfg");
    std::string ln;
    while (std::getline(f, ln)) {
        std::vector<std::string> c; std::size_t s = 0;
        for (std::size_t i = 0; i <= ln.size(); ++i) if (i == ln.size() || ln[i] == '\t') { c.push_back(ln.substr(s, i - s)); s = i + 1; }
        if (c.size() < 6) continue;
        SchedMsg m;
        m.id = std::atol(c[0].c_str()); m.at = std::atol(c[1].c_str()); m.toGroup = std::atol(c[2].c_str());
        m.toUid = SchedUnesc(c[3]); m.toName = SchedUnesc(c[4]); m.body = SchedUnesc(c[5]);
        if (m.id > 0 && !m.body.empty() && (m.toGroup > 0 || !m.toUid.empty())) g_scheduled.push_back(m);
    }
}
static void ScheduleMessage(const std::string& toUid, const std::string& toName, long toGroup, const std::string& body, long at) {
    long id = 1; for (const auto& m : g_scheduled) id = std::max(id, m.id + 1);
    g_scheduled.push_back(SchedMsg{id, toUid, toName, toGroup, body, at});
    std::sort(g_scheduled.begin(), g_scheduled.end(), [](const SchedMsg& a, const SchedMsg& b) { return a.at < b.at; });
    SaveScheduled();
}
// When a time is, in words: "today at 18:30", "tomorrow at 09:00", "Fri 12 Jan at 09:00".
static std::string SchedWhen(long at) {
    std::time_t t = (std::time_t)at, now = std::time(nullptr);
    std::tm a = *std::localtime(&t), n = *std::localtime(&now);
    char hm[16]; std::strftime(hm, sizeof(hm), "%H:%M", &a);
    std::tm n1 = n; n1.tm_mday += 1; std::mktime(&n1);
    if (a.tm_year == n.tm_year && a.tm_yday == n.tm_yday) return std::string("today at ") + hm;
    if (a.tm_year == n1.tm_year && a.tm_yday == n1.tm_yday) return std::string("tomorrow at ") + hm;
    char d[32]; std::strftime(d, sizeof(d), "%a %d %b", &a);
    return std::string(d) + " at " + hm;
}
// Once a frame: send anything that's due.
static void PumpScheduled(bool signedIn) {
    if (!signedIn || g_scheduled.empty() || ChatDemo()) return;
    const long now = (long)std::time(nullptr);
    bool changed = false;
    for (std::size_t i = 0; i < g_scheduled.size();) {
        if (g_scheduled[i].at <= now) {
            const SchedMsg m = g_scheduled[i];
            OutboxSend(m.toUid, m.toGroup, m.body);
            Toast("Sent your scheduled message" + (m.toName.empty() ? std::string() : " to " + m.toName), 1);
            g_scheduled.erase(g_scheduled.begin() + (long)i);
            changed = true;
        } else ++i;
    }
    if (changed) SaveScheduled();
}
// "Schedule message" dialog for one conversation. `text` is the composer's
// buffer (prefilled into the dialog, cleared when scheduled).
bool g_schedOpenReq = false;   // the composer's "+" menu asked for it
void DrawScheduleDialog(const char* popupId, char* text, std::size_t cap,
                               const std::string& toUid, const std::string& toName, long toGroup) {
    static char body[1024] = "";
    static int preset = 1;
    static char dateBuf[16] = "", timeBuf[8] = "";
    if (!ImGui::IsPopupOpen(popupId) && g_schedOpenReq) {
        g_schedOpenReq = false;
        std::snprintf(body, sizeof(body), "%s", text);
        std::time_t t = std::time(nullptr) + 3600; std::tm lt = *std::localtime(&t);
        std::strftime(dateBuf, sizeof(dateBuf), "%Y-%m-%d", &lt);
        std::strftime(timeBuf, sizeof(timeBuf), "%H:%M", &lt);
        preset = 1;
        ImGui::OpenPopup(popupId);
    }
    ImGui::SetNextWindowSize(ImVec2(440, 0), ImGuiCond_Appearing);
    if (!ImGui::BeginPopupModal(popupId, nullptr, ImGuiWindowFlags_AlwaysAutoResize)) return;
    ImGui::TextDisabled("To %s", toName.empty() ? "this chat" : toName.c_str());
    ImGui::InputTextMultiline("##schedbody", body, sizeof(body), ImVec2(420, ImGui::GetTextLineHeight() * 4 + 16));
    ImGui::Dummy(ImVec2(0, 4));
    ImGui::TextUnformatted("Send");
    // Presets resolve to a time; "Pick a time" uses the date / time boxes.
    const std::time_t now = std::time(nullptr);
    std::tm lt = *std::localtime(&now);
    auto at = [&](int addDays, int hour, int minute) {
        std::tm x = lt; x.tm_mday += addDays; x.tm_hour = hour; x.tm_min = minute; x.tm_sec = 0; x.tm_isdst = -1;
        return (long)std::mktime(&x);
    };
    const long tonight = at(lt.tm_hour >= 20 ? 1 : 0, 20, 0);
    const long tomorrowAm = at(1, 9, 0);
    const int daysToMon = ((8 - lt.tm_wday) % 7 == 0) ? 7 : (8 - lt.tm_wday) % 7;
    struct Opt { const char* label; long when; };
    const Opt opts[] = {
        {"In 30 minutes", (long)now + 30 * 60}, {"In 1 hour", (long)now + 3600}, {"In 3 hours", (long)now + 3 * 3600},
        {lt.tm_hour >= 20 ? "Tomorrow evening (20:00)" : "This evening (20:00)", tonight},
        {"Tomorrow morning (09:00)", tomorrowAm}, {"Monday morning (09:00)", at(daysToMon, 9, 0)},
        {"Pick a date and time", 0},
    };
    const int nOpts = (int)(sizeof(opts) / sizeof(opts[0]));
    for (int k = 0; k < nOpts; ++k) {
        if (ImGui::RadioButton(opts[k].label, preset == k)) preset = k;
        if (opts[k].when > 0) { ImGui::SameLine(); ImGui::TextDisabled("%s", SchedWhen(opts[k].when).c_str()); }
    }
    long when = preset < nOpts - 1 ? opts[preset].when : 0;
    if (preset == nOpts - 1) {
        ImGui::Indent(24.0f);
        ImGui::SetNextItemWidth(110); ImGui::InputTextWithHint("##sdate", "YYYY-MM-DD", dateBuf, sizeof(dateBuf));
        ImGui::SameLine(); ImGui::SetNextItemWidth(70); ImGui::InputTextWithHint("##stime", "HH:MM", timeBuf, sizeof(timeBuf));
        int Y = 0, Mo = 0, D = 0, h = 0, mi = 0;
        if (std::sscanf(dateBuf, "%d-%d-%d", &Y, &Mo, &D) == 3 && std::sscanf(timeBuf, "%d:%d", &h, &mi) == 2 &&
            Mo >= 1 && Mo <= 12 && D >= 1 && D <= 31 && h >= 0 && h < 24 && mi >= 0 && mi < 60) {
            std::tm x{}; x.tm_year = Y - 1900; x.tm_mon = Mo - 1; x.tm_mday = D; x.tm_hour = h; x.tm_min = mi; x.tm_isdst = -1;
            when = (long)std::mktime(&x);
            ImGui::SameLine(); ImGui::TextDisabled("%s", when > (long)now ? SchedWhen(when).c_str() : "that's in the past");
        } else { ImGui::SameLine(); ImGui::TextDisabled("enter a date and time"); }
        ImGui::Unindent(24.0f);
    }
    ImGui::Dummy(ImVec2(0, 4));
    ImGui::TextDisabled("OkaySpace sends it at that time if the launcher is open (or as soon as it next opens).");
    ImGui::Dummy(ImVec2(0, 4));
    std::string b = body; while (!b.empty() && (b.back() == ' ' || b.back() == '\n')) b.pop_back();
    const bool ok = !b.empty() && when > (long)now;
    if (ImGui::Button("Cancel", ImVec2(okl::FitButtonW("Cancel", okl::UiPx(100.0f)), okl::UiPx(30.0f)))) ImGui::CloseCurrentPopup();
    ImGui::SameLine();
    ImGui::BeginDisabled(!ok);
    if (PrimaryButton("Schedule", ImVec2(okl::FitButtonW("Schedule", okl::UiPx(120.0f)), okl::UiPx(30.0f)))) {
        ScheduleMessage(toUid, toName, toGroup, ExpandCustomEmoji(b.c_str()), when);
        Toast("Scheduled for " + SchedWhen(when), 1);
        text[0] = '\0'; (void)cap;
        ImGui::CloseCurrentPopup();
    }
    ImGui::EndDisabled();
    ImGui::EndPopup();
}
// A slim line above the composer when this chat has scheduled messages, with
// a popup to send one now, edit its time (reschedule) or delete it.
void DrawScheduledStrip(const std::string& toUid, long toGroup) {
    std::vector<SchedMsg*> mine;
    for (auto& m : g_scheduled) if ((toGroup > 0 && m.toGroup == toGroup) || (toGroup == 0 && m.toGroup == 0 && m.toUid == toUid)) mine.push_back(&m);
    if (mine.empty()) return;
    ImGui::PushID(toGroup > 0 ? ("sg" + std::to_string(toGroup)).c_str() : ("su" + toUid).c_str());
    const ImVec2 p = ImGui::GetCursorScreenPos();
    const float lh = ImGui::GetTextLineHeight();
    ImDrawList* d = ImGui::GetWindowDrawList();
    const ImU32 col = ImGui::GetColorU32(okaytheme::AccentText(kAccent));
    const ImVec2 cc(p.x + 8, p.y + lh * 0.5f);
    d->AddCircle(cc, 6.0f, col, 16, 1.4f);
    d->AddLine(cc, ImVec2(cc.x, cc.y - 3.5f), col, 1.4f); d->AddLine(cc, ImVec2(cc.x + 3.0f, cc.y), col, 1.4f);
    ImGui::SetCursorScreenPos(ImVec2(p.x + 20, p.y));
    char lbl[96];
    if (mine.size() == 1) std::snprintf(lbl, sizeof(lbl), "1 scheduled message \xC2\xB7 %s", SchedWhen(mine[0]->at).c_str());
    else std::snprintf(lbl, sizeof(lbl), "%d scheduled messages \xC2\xB7 next %s", (int)mine.size(), SchedWhen(mine[0]->at).c_str());
    ImGui::PushStyleColor(ImGuiCol_Text, ImGui::ColorConvertU32ToFloat4(col));
    if (ImGui::Selectable(lbl, false, 0, ImVec2(ImGui::CalcTextSize(lbl).x, 0))) ImGui::OpenPopup("##schedlist");
    ImGui::PopStyleColor();
    if (ImGui::IsItemHovered()) ImGui::SetTooltip("See, send now or cancel");
    ImGui::SetNextWindowSizeConstraints(ImVec2(320, 0), ImVec2(480, 400));
    if (ImGui::BeginPopup("##schedlist")) {
        ImGui::TextDisabled("Scheduled messages");
        ImGui::Separator();
        long sendNow = 0, drop = 0;
        for (SchedMsg* m : mine) {
            ImGui::PushID((int)m->id);
            ImGui::TextColored(okaytheme::AccentText(kAccent), "%s", SchedWhen(m->at).c_str());
            const ImVec2 rp = ImGui::GetCursorScreenPos();
            DrawRichLine(ImGui::GetWindowDrawList(), rp, ImGui::GetColorU32(ImGuiCol_Text), ChatPreviewSmart(m->body, 120), 300.0f);
            ImGui::Dummy(ImVec2(300, lh));
            if (ImGui::SmallButton("Send now")) sendNow = m->id;
            ImGui::SameLine();
            if (ImGui::SmallButton("Later +1h")) { m->at += 3600; SaveScheduled(); }
            ImGui::SameLine();
            if (ImGui::SmallButton("Delete")) drop = m->id;
            ImGui::Separator();
            ImGui::PopID();
        }
        for (std::size_t i = 0; i < g_scheduled.size(); ++i) {
            if (g_scheduled[i].id == sendNow) {
                if (!ChatDemo()) OutboxSend(g_scheduled[i].toUid, g_scheduled[i].toGroup, g_scheduled[i].body);
                g_scheduled.erase(g_scheduled.begin() + (long)i); SaveScheduled(); Toast("Sent", 1); break;
            }
            if (g_scheduled[i].id == drop) { g_scheduled.erase(g_scheduled.begin() + (long)i); SaveScheduled(); Toast("Scheduled message deleted", 1); break; }
        }
        ImGui::EndPopup();
    }
    ImGui::PopID();
}

// ---- Custom status -----------------------------------------------------------------
// profiles.status: a short line with an emoji ("🎮 Playing Neon Drift"), shown
// next to your name in chats and on the Friends list. It can clear itself
// after a while; this launcher clears it when that time comes (or on its next
// start, if it was closed then).
static volatile bool g_statusBusy = false;
static int StatusSaveWorker(void* p) {
    std::unique_ptr<std::string> s(static_cast<std::string*>(p));
    try {
        okay::account::AccountService a(fs::path(g_pollCfgDir), g_pollUrl, g_pollKey);
        okay::Friends(a).SetStatus(*s);
    } catch (...) {}
    g_statusBusy = false;
    return 0;
}
static int StatusFetchWorker(void*) {
    std::string s; bool ok = false;
    try {
        okay::account::AccountService a(fs::path(g_pollCfgDir), g_pollUrl, g_pollKey);
        if (a.IsLoggedIn()) { s = okay::Friends(a).MyStatus(); ok = true; }
    } catch (...) {}
    if (ok && !g_myStatusKnown) { g_myStatus = s; g_myStatusKnown = true; }
    g_statusBusy = false;
    return 0;
}
static void SetMyStatus(const std::string& text, long until) {
    g_myStatus = text; g_myStatusKnown = true; g_statusUntil = text.empty() ? 0 : until;
    SavePrefs();
    if (ChatDemo()) return;
    g_statusBusy = true;
    auto* s = new std::string(text);
    if (okay::thr::Thread* t = okay::thr::CreateThread(StatusSaveWorker, "okay-status", s)) okay::thr::DetachThread(t);
    else { delete s; g_statusBusy = false; }
}
// Once a frame (main loop): learn my status once after sign-in, clear it when due.
static void PumpStatus(bool signedIn) {
    if (!signedIn) return;
    if (!g_myStatusKnown && !g_statusBusy && !ChatDemo() && !g_pollCfgDir.empty()) {
        static Uint32 nextTry = 0;
        if (okay::platform::TicksMs32() >= nextTry) {
            nextTry = okay::platform::TicksMs32() + 30000;
            g_statusBusy = true;
            if (okay::thr::Thread* t = okay::thr::CreateThread(StatusFetchWorker, "okay-statusget", nullptr)) okay::thr::DetachThread(t);
            else g_statusBusy = false;
        }
    }
    if (g_statusUntil > 0 && (long)std::time(nullptr) >= g_statusUntil && !g_statusBusy) {
        SetMyStatus("", 0);
        Toast("Your status was cleared", 0);
    }
}
static bool g_statusDialogReq = false;       // the launcher's profile card asked for the dialog
static bool g_statusDialogReqChat = false;   // the chat window asked (it may be its own OS window)
static void DrawStatusDialog(bool& req) {
    static char text[96] = "";
    static int clearAfter = 0;   // index into kClear
    static const char* kClear[] = {"Don't clear", "30 minutes", "1 hour", "4 hours", "Today", "This week"};
    if (req) {
        req = false;
        std::snprintf(text, sizeof(text), "%s", g_myStatus.c_str());
        clearAfter = 0;
        ImGui::OpenPopup("Set a status");
    }
    ImGui::SetNextWindowSize(ImVec2(420, 0), ImGuiCond_Appearing);
    if (!ImGui::BeginPopupModal("Set a status", nullptr, ImGuiWindowFlags_AlwaysAutoResize)) return;
    ImGui::TextDisabled("Shown next to your name in chats and on your friends' lists.");
    ImGui::Dummy(ImVec2(0, 2));
    // Emoji button (inserts into the text) + the text box + a live preview.
    ChatMediaPicker("statusemoji", text, sizeof(text), nullptr, false);
    ImGui::SameLine(0, 6);
    ImGui::SetNextItemWidth(360);
    ImGui::InputTextWithHint("##status", "What's happening?", text, sizeof(text));
    if (text[0]) {
        const ImVec2 pp = ImGui::GetCursorScreenPos();
        ImGui::TextDisabled("Preview:");
        DrawRichLine(ImGui::GetWindowDrawList(), ImVec2(pp.x + ImGui::CalcTextSize("Preview:  ").x, pp.y),
                     ImGui::GetColorU32(ImGuiCol_Text), text, 330.0f);
    }
    ImGui::Dummy(ImVec2(0, 4));
    ImGui::TextDisabled("Suggestions");
    struct Preset { const char* text; int clear; };
    static const Preset kPresets[] = {
        {"\xF0\x9F\x8E\xAE Playing games", 3}, {"\xF0\x9F\x9B\xA0\xEF\xB8\x8F Working on my game", 4},
        {"\xF0\x9F\x93\x85 In a meeting", 2}, {"\xF0\x9F\x8E\xA7 Listening to music", 2},
        {"\xF0\x9F\xA4\x92 Out sick", 4}, {"\xF0\x9F\x8C\xB4 On vacation", 5}, {"\xF0\x9F\x98\xB4 Away for a bit", 1},
    };
    for (const auto& pr : kPresets) {
        ImGui::PushID(pr.text);
        const ImVec2 rp = ImGui::GetCursorScreenPos();
        if (ImGui::Selectable("##preset", false, 0, ImVec2(400, ImGui::GetTextLineHeight() + 4))) {
            std::snprintf(text, sizeof(text), "%s", pr.text); clearAfter = pr.clear;
        }
        DrawRichLine(ImGui::GetWindowDrawList(), ImVec2(rp.x + 6, rp.y + 2), ImGui::GetColorU32(ImGuiCol_Text), pr.text, 260.0f);
        ImGui::GetWindowDrawList()->AddText(ImVec2(rp.x + 290, rp.y + 2), ImGui::GetColorU32(ImGuiCol_TextDisabled), kClear[pr.clear]);
        ImGui::PopID();
    }
    ImGui::Dummy(ImVec2(0, 4));
    ImGui::AlignTextToFramePadding();
    ImGui::TextUnformatted("Clear after"); ImGui::SameLine();
    ImGui::SetNextItemWidth(160);
    SlateCombo("##clearafter", &clearAfter, kClear, (int)(sizeof(kClear) / sizeof(kClear[0])));
    ImGui::Dummy(ImVec2(0, 6));
    if (!g_myStatus.empty()) {
        if (ImGui::Button("Clear status", ImVec2(okl::FitButtonW("Clear status", okl::UiPx(120.0f)), okl::UiPx(30.0f)))) { SetMyStatus("", 0); Toast("Status cleared", 1); ImGui::CloseCurrentPopup(); }
        ImGui::SameLine();
    }
    if (ImGui::Button("Cancel", ImVec2(okl::FitButtonW("Cancel", okl::UiPx(90.0f)), okl::UiPx(30.0f)))) ImGui::CloseCurrentPopup();
    ImGui::SameLine();
    std::string t = text; while (!t.empty() && t.back() == ' ') t.pop_back();
    if (PrimaryButton("Save", ImVec2(okl::FitButtonW("Save", okl::UiPx(100.0f)), okl::UiPx(30.0f)))) {
        long until = 0;
        const std::time_t now = std::time(nullptr);
        switch (clearAfter) {
            case 1: until = (long)now + 30 * 60; break;
            case 2: until = (long)now + 3600; break;
            case 3: until = (long)now + 4 * 3600; break;
            case 4: { std::tm x = *std::localtime(&now); x.tm_hour = 23; x.tm_min = 59; x.tm_sec = 59; x.tm_isdst = -1; until = (long)std::mktime(&x); break; }
            case 5: { std::tm x = *std::localtime(&now); x.tm_mday += (7 - x.tm_wday) % 7; x.tm_hour = 23; x.tm_min = 59; x.tm_sec = 59; x.tm_isdst = -1; until = (long)std::mktime(&x); break; }
            default: break;
        }
        SetMyStatus(t, until);
        Toast(t.empty() ? "Status cleared" : "Status updated", 1);
        ImGui::CloseCurrentPopup();
    }
    if (g_statusUntil > 0 && !g_myStatus.empty()) { ImGui::SameLine(); ImGui::TextDisabled("clears %s", SchedWhen(g_statusUntil).c_str()); }
    ImGui::EndPopup();
}

// ---- Search across every chat --------------------------------------------------
static okay::thr::Mutex* g_srchMutex = nullptr;
static volatile bool g_srchBusy = false;
static std::string g_srchQuery;                                    // (guarded) what the results are for
static std::vector<okay::Messages::SearchHit> g_srchHits;          // (guarded)
static bool g_srchReady = false;                                   // (guarded)
static int ChatSearchWorker(void* p) {
    std::unique_ptr<std::string> q(static_cast<std::string*>(p));
    std::vector<okay::Messages::SearchHit> hits;
    try {
        okay::account::AccountService a(fs::path(g_pollCfgDir), g_pollUrl, g_pollKey);
        hits = okay::Messages(a).Search(*q, 40);
    } catch (...) {}
    okay::thr::LockMutex(g_srchMutex);
    g_srchQuery = *q; g_srchHits = std::move(hits); g_srchReady = true;
    okay::thr::UnlockMutex(g_srchMutex);
    g_srchBusy = false;
    return 0;
}
static void ChatSearchStart(const std::string& q) {
    if (!g_srchMutex) g_srchMutex = okay::thr::CreateMutex();
    if (g_srchBusy) return;
    g_srchBusy = true;
    auto* s = new std::string(q);
    if (okay::thr::Thread* t = okay::thr::CreateThread(ChatSearchWorker, "okay-chatsearch", s)) okay::thr::DetachThread(t);
    else { delete s; g_srchBusy = false; }
}

// ---- Forwarding ------------------------------------------------------------------
// Any message (DM or group) can be forwarded to several friends and groups at
// once, optionally with a note. Drawn by the chat window (it has the lists).
long g_chatJumpGroup = 0;   // a group message to scroll to once its thread is open
static bool g_fwdOpenReq = false;
static std::string g_fwdBody, g_fwdFrom;   // what to forward and who wrote it
void ChatForward(const std::string& body, const std::string& from) {
    g_fwdBody = body; g_fwdFrom = from; g_fwdOpenReq = true;
}

// Little line icons for message toolbars.
static void DrawReplyIcon(ImDrawList* d, ImVec2 c, ImU32 col) {   // curved "reply" arrow
    d->PathArcTo(ImVec2(c.x + 1.0f, c.y + 4.0f), 6.0f, 3.14159265f * 1.5f, 3.14159265f * 2.0f, 8);
    d->PathStroke(col, 0, 1.6f);
    d->AddLine(ImVec2(c.x - 6, c.y - 2), ImVec2(c.x + 1, c.y - 2), col, 1.6f);
    d->AddLine(ImVec2(c.x - 6, c.y - 2), ImVec2(c.x - 2.5f, c.y - 5.5f), col, 1.6f);
    d->AddLine(ImVec2(c.x - 6, c.y - 2), ImVec2(c.x - 2.5f, c.y + 1.5f), col, 1.6f);
}
static void DrawThreadIcon(ImDrawList* d, ImVec2 c, ImU32 col) {   // two speech bubbles
    d->AddRect(ImVec2(c.x - 7, c.y - 6), ImVec2(c.x + 3, c.y + 1), col, 3.0f, 0, 1.4f);
    d->AddLine(ImVec2(c.x - 4, c.y + 1), ImVec2(c.x - 5, c.y + 4), col, 1.4f);
    d->AddRect(ImVec2(c.x - 1, c.y - 1), ImVec2(c.x + 7, c.y + 5), col, 3.0f, 0, 1.4f);
}
static void DrawPencilIcon(ImDrawList* d, ImVec2 c, ImU32 col) {
    d->AddLine(ImVec2(c.x - 5, c.y + 5), ImVec2(c.x + 4, c.y - 4), col, 2.2f);
    d->AddLine(ImVec2(c.x - 6, c.y + 6), ImVec2(c.x - 4.5f, c.y + 4.5f), col, 1.2f);
}
void DrawDotsIcon(ImDrawList* d, ImVec2 c, ImU32 col) {   // "more" (⋯)
    for (int k = -1; k <= 1; ++k) d->AddCircleFilled(ImVec2(c.x + k * 5.0f, c.y), 1.7f, col, 8);
}

// Discord-style toolbar over the hovered message, shared by DMs, groups and
// server channels so they work the same: 'L' like, 'R' reply, 'T' thread,
// 'E' edit, 'M' more. Drawn in its own child window so it sits on top of the
// bubble, and it stays up while the mouse moves from the message onto it.
// Returns the index of the clicked button, or -1.
int ChatMsgToolbar(long msgId, ImVec2 rowMin, ImVec2 rowMax, const ChatTbBtn* btns, int nb, bool liked) {
    static long s_owner = 0; static ImVec2 s_min, s_max; static int s_frame = -1;
    if (!ImGui::IsWindowHovered(ImGuiHoveredFlags_ChildWindows | ImGuiHoveredFlags_AllowWhenBlockedByActiveItem)) return -1;
    const float bs = 28.0f;
    const ImVec2 tb(rowMax.x - nb * bs - 10, std::max(rowMin.y - 16, ImGui::GetWindowPos().y + 2));
    const ImVec2 tMin(tb.x - 3, tb.y - 2), tMax(tb.x + nb * bs + 3, tb.y + bs + 2);
    const bool ownerLive = s_owner != 0 && s_frame >= ImGui::GetFrameCount() - 1;
    const bool onOwnerBar = ownerLive && ImGui::IsMouseHoveringRect(s_min, s_max, false);
    if (onOwnerBar ? s_owner != msgId : !ImGui::IsMouseHoveringRect(rowMin, rowMax, false)) return -1;
    s_owner = msgId; s_min = tMin; s_max = tMax; s_frame = ImGui::GetFrameCount();
    ImGui::GetWindowDrawList()->AddRectFilled(ImVec2(rowMin.x - 6, rowMin.y - 2), ImVec2(rowMax.x + 6, rowMax.y + 2), okaytheme::Ink(7), 8.0f);
    const ImVec2 after = ImGui::GetCursorScreenPos();
    ImGui::SetCursorScreenPos(tMin);
    ImGui::PushStyleVar(ImGuiStyleVar_WindowPadding, ImVec2(3, 2));
    ImGui::PushStyleVar(ImGuiStyleVar_ChildRounding, 8.0f);
    ImGui::PushStyleVar(ImGuiStyleVar_ChildBorderSize, 1.0f);
    ImGui::PushStyleVar(ImGuiStyleVar_ItemSpacing, ImVec2(0, 0));
    ImGui::PushStyleColor(ImGuiCol_ChildBg, okaytheme::kRaised);
    ImGui::PushStyleColor(ImGuiCol_Border, okaytheme::InkV(0.086f));
    int clicked = -1;
    if (ImGui::BeginChild("##chatmsgtb", ImVec2(tMax.x - tMin.x, tMax.y - tMin.y), ImGuiChildFlags_Borders,
                          ImGuiWindowFlags_NoScrollbar | ImGuiWindowFlags_NoScrollWithMouse | ImGuiWindowFlags_NoSavedSettings)) {
        ImDrawList* d = ImGui::GetWindowDrawList();
        const ImU32 cText = ImGui::GetColorU32(ImGuiCol_Text);
        for (int b = 0; b < nb; ++b) {
            ImGui::PushID(b);
            if (b) ImGui::SameLine(0, 0);
            const ImVec2 bp = ImGui::GetCursorScreenPos();
            if (ImGui::InvisibleButton("##tb", ImVec2(bs, bs))) clicked = b;
            const bool h = ImGui::IsItemHovered();
            if (h) d->AddRectFilled(ImVec2(bp.x + 2, bp.y + 2), ImVec2(bp.x + bs - 2, bp.y + bs - 2), okaytheme::Ink(26), 6.0f);
            const ImVec2 c(bp.x + bs * 0.5f, bp.y + bs * 0.5f);
            const ImU32 ic = h ? cText : okaytheme::TextU32(0.902f);
            switch (btns[b].icon) {
                case 'L': DrawHeart(d, c, 6.0f, liked ? okaytheme::DangerFillU32() : ic); break;
                case 'R': DrawReplyIcon(d, c, ic); break;
                case 'T': DrawThreadIcon(d, c, ic); break;
                case 'E': DrawPencilIcon(d, c, ic); break;
                default:  DrawDotsIcon(d, c, ic); break;
            }
            if (h) { ImGui::SetMouseCursor(ImGuiMouseCursor_Hand); ImGui::SetTooltip("%s", btns[b].tip); }
            ImGui::PopID();
        }
    }
    ImGui::EndChild();
    ImGui::PopStyleColor(2);
    ImGui::PopStyleVar(4);
    ImGui::SetCursorScreenPos(after);
    return clicked;
}

// Flat icon button for chat headers (call, ⋯, search, members): no frame, a
// soft rounded highlight on hover / while `active`. The caller draws the glyph
// centred on *centre.
bool ChatHeaderIconButton(const char* id, ImVec2 pos, bool active, const char* tip, ImVec2* centre) {
    ImGui::SetCursorScreenPos(pos);
    const bool hit = ImGui::InvisibleButton(id, ImVec2(30, 30));
    const bool h = ImGui::IsItemHovered(ImGuiHoveredFlags_AllowWhenDisabled);
    if (h || active) ImGui::GetWindowDrawList()->AddRectFilled(pos, ImVec2(pos.x + 30, pos.y + 30),
                                                               h ? okaytheme::Ink(22) : okaytheme::Ink(10), 8.0f);
    if (h && tip && *tip) ImGui::SetTooltip("%s", tip);
    *centre = ImVec2(pos.x + 15, pos.y + 15);
    return hit;
}

static void OutboxSendChannel(long channelId, const std::string& body) { OutboxSend(std::string(), 0, body, 0, channelId); }
// My pending posts for a server channel, after dropping the ones the channel log
// now contains (inLog(body, when)).
static std::vector<OutMsg> OutboxForChannel(long channelId, const std::function<bool(const std::string&, long)>& inLog) {
    std::vector<OutMsg> pend;
    if (!g_outMutex || channelId <= 0) return pend;
    okay::thr::LockMutex(g_outMutex);
    const Uint32 now = okay::platform::TicksMs32();
    g_outbox.erase(std::remove_if(g_outbox.begin(), g_outbox.end(), [&](const OutMsg& o) {
        return o.toChannel == channelId && o.state == 1 && (inLog(o.body, o.when) || now - o.sentAt > 15000);
    }), g_outbox.end());
    for (const auto& o : g_outbox) if (o.toChannel == channelId) pend.push_back(o);
    okay::thr::UnlockMutex(g_outMutex);
    return pend;
}
static void OutboxRetry(long localId) {
    if (!g_outMutex) return;
    okay::thr::LockMutex(g_outMutex);
    for (auto& x : g_outbox) if (x.localId == localId) x.state = 0;
    okay::thr::UnlockMutex(g_outMutex);
    OutboxKick();
}
static void OutboxDiscard(long localId) {
    if (!g_outMutex) return;
    okay::thr::LockMutex(g_outMutex);
    g_outbox.erase(std::remove_if(g_outbox.begin(), g_outbox.end(), [&](const OutMsg& x) { return x.localId == localId; }), g_outbox.end());
    okay::thr::UnlockMutex(g_outMutex);
}
// Draw my pending messages for one conversation (right-aligned, after the log)
// and drop the ones the log now contains. inLog(body, when) says whether the
// real message has arrived.
int DrawOutbox(const std::string& uid, long gid, float avW, float baseX, ImVec4 bubbleCol,
                      const std::function<bool(const std::string&, long)>& inLog) {
    if (!g_outMutex) return 0;
    std::vector<OutMsg> pend;
    okay::thr::LockMutex(g_outMutex);
    const Uint32 now = okay::platform::TicksMs32();
    g_outbox.erase(std::remove_if(g_outbox.begin(), g_outbox.end(), [&](const OutMsg& o) {
        return o.toChannel == 0 && o.state == 1 && (inLog(o.body, o.when) || now - o.sentAt > 15000);
    }), g_outbox.end());
    for (const auto& o : g_outbox) if (o.toChannel == 0 && o.toGroup == gid && (gid > 0 || o.toUid == uid)) pend.push_back(o);
    okay::thr::UnlockMutex(g_outMutex);
    const float padX = 14.0f, padY = 8.0f;
    for (const auto& o : pend) {
        const float bubbleMax = std::min(avW * 0.72f, 460.0f);
        const float bodyW = MeasureChatBodyWidth(o.body, bubbleMax - padX * 2);
        const char* status = o.state == -1 ? "Not sent" : o.state == 1 ? "Sent" : "Sending";
        float statW = ImGui::CalcTextSize(status).x + (o.state == -1 ? 120.0f : 20.0f);
        if (o.state == -1 && !o.err.empty()) statW = std::max(statW, std::min(bubbleMax - padX * 2, ImGui::CalcTextSize(o.err.c_str()).x * 0.55f + 16.0f));
        const float useW = std::max(std::max(bodyW + 2.0f, statW) + padX * 2, 46.0f);
        ImGui::Dummy(ImVec2(0, 2));
        ImGui::SetCursorPosX(baseX + std::max(0.0f, avW - useW - 8.0f));
        ImGui::PushID((int)o.localId);
        ImVec4 bg = o.state == -1 ? okaytheme::DangerFill() : ImVec4(bubbleCol.x, bubbleCol.y, bubbleCol.z, 0.78f);
        ImGui::PushStyleColor(ImGuiCol_ChildBg, bg);
        ImGui::PushStyleVar(ImGuiStyleVar_ChildRounding, 14.0f);
        ImGui::PushStyleVar(ImGuiStyleVar_WindowPadding, ImVec2(padX, padY));
        ImGui::BeginChild("##outbub", ImVec2(useW, 0), ImGuiChildFlags_AutoResizeY | ImGuiChildFlags_AlwaysUseWindowPadding,
                          ImGuiWindowFlags_NoScrollbar | ImGuiWindowFlags_NoScrollWithMouse);
        ImGui::PushStyleVar(ImGuiStyleVar_ItemSpacing, ImVec2(4, 2));
        RenderChatBody(o.body, ImGui::GetContentRegionAvail().x);
        // Status line (right): a little clock while sending, Retry/Discard on failure.
        const float av = ImGui::GetContentRegionAvail().x;
        if (o.state == -1) {
            ImGui::SetCursorPosX(ImGui::GetCursorPosX() + std::max(0.0f, av - statW));
            ImGui::TextColored(okaytheme::Current().danger, "%s", status);
            ImGui::SameLine(0, 8);
            if (ImGui::SmallButton("Retry")) {
                okay::thr::LockMutex(g_outMutex);
                for (auto& x : g_outbox) if (x.localId == o.localId) x.state = 0;
                okay::thr::UnlockMutex(g_outMutex);
                OutboxKick();
            }
            ImGui::SameLine(0, 4);
            if (ImGui::SmallButton("Discard")) {
                okay::thr::LockMutex(g_outMutex);
                g_outbox.erase(std::remove_if(g_outbox.begin(), g_outbox.end(), [&](const OutMsg& x) { return x.localId == o.localId; }), g_outbox.end());
                okay::thr::UnlockMutex(g_outMutex);
            }
            if (!o.err.empty()) {   // the server said why (e.g. "This person does not accept messages from you.")
                ImGui::PushTextWrapPos(0.0f);
                ImGui::TextColored(okaytheme::Current().danger, "%s", o.err.c_str());
                ImGui::PopTextWrapPos();
            }
        } else {
            const float tw = ImGui::CalcTextSize(status).x;
            ImGui::SetCursorPosX(ImGui::GetCursorPosX() + std::max(0.0f, av - tw - 16.0f));
            ImVec2 cp = ImGui::GetCursorScreenPos();
            const float r = 5.0f, cy = cp.y + ImGui::GetTextLineHeight() * 0.5f;
            ImDrawList* dl = ImGui::GetWindowDrawList();
            const ImU32 cc = okaytheme::TextU32(0.667f);
            dl->AddCircle(ImVec2(cp.x + r, cy), r, cc, 12, 1.2f);   // clock face + hands
            dl->AddLine(ImVec2(cp.x + r, cy), ImVec2(cp.x + r, cy - 3.2f), cc, 1.2f);
            dl->AddLine(ImVec2(cp.x + r, cy), ImVec2(cp.x + r + 2.4f, cy), cc, 1.2f);
            ImGui::Dummy(ImVec2(14, 0)); ImGui::SameLine(0, 2);
            ImGui::TextColored(okaytheme::WithAlpha(okaytheme::kText, 0.65f), "%s", status);
        }
        ImGui::PopStyleVar();
        ImGui::EndChild();
        ImGui::PopStyleVar(2);
        ImGui::PopStyleColor();
        ImGui::PopID();
    }
    return (int)pend.size();
}
static volatile bool g_chatTypingReq = false;  // the composer asks the worker to broadcast "typing"
static std::string g_chatSelUid;                                        // (guarded) open conversation
static bool g_chatLogReady = false, g_chatConvReady = false, g_chatFriReady = false;  // (guarded)
static std::vector<okay::DirectMessage> g_chatLog;                      // (guarded)
static std::map<long, std::map<std::string,long>> g_chatReacts;        // (guarded)
static std::map<long, std::set<std::string>> g_chatMyReacts;           // (guarded)
static long g_chatPeerRead = 0;                                         // (guarded)
static bool g_chatPeerHere = false;        // (guarded) the peer has our chat open right now
static long g_chatPeerLastSeen = 0;        // (guarded) peer's last online heartbeat (unix)
static std::string g_chatPeerStateUid;     // (guarded) which conversation the three above describe
